typedef struct {
  UF_long *panel_run_count;
  UF_long *panel_run_rows;
  UF_long *panel_small_run_count;
  UF_long *panel_small_run_rows;
  UF_long *column_run_count;
  UF_long run_count;
  UF_long run_rows;
  UF_long small_run_count;
  UF_long small_run_rows;
  double l_entries;
  double internal_entries;
} kls_supernode_consumer_plan_count_context;

static int kls_count_supernode_consumer_plan_run(
  kls_solver *solver,
  const kls_supernode_consumer_run_info *run,
  void *context) {
  kls_supernode_consumer_plan_count_context *ctx =
    (kls_supernode_consumer_plan_count_context *)context;
  if (solver == NULL || run == NULL || ctx == NULL) {
    return 0;
  }
  if (run->panel_start >= solver->n) {
    return 1;
  }
  ctx->panel_run_count[run->panel_start]++;
  ctx->panel_run_rows[run->panel_start] += run->run_rows;
  if (run->run_rows < KLS_EGRAPH_RAGGED_U_SUPERNODE_MIN_ROWS) {
    ctx->panel_small_run_count[run->panel_start]++;
    ctx->panel_small_run_rows[run->panel_start] += run->run_rows;
    ctx->small_run_count++;
    ctx->small_run_rows += run->run_rows;
  }
  ctx->column_run_count[run->current_global]++;
  ctx->run_count++;
  ctx->run_rows += run->run_rows;
  ctx->l_entries += run->l_entries;
  ctx->internal_entries += run->internal_entries;
  return 1;
}

typedef struct {
  UF_long *cursor;
  UF_long *plan_ptr;
  UF_long *plan_current;
  UF_long *plan_dep;
  UF_long *plan_rows;
  UF_long *plan_panel_start;
  UF_long *plan_panel_offset;
  UF_long *column_cursor;
  UF_long *column_ptr;
  UF_long *column_runs;
} kls_supernode_consumer_plan_fill_context;

static int kls_fill_supernode_consumer_plan_run(
  kls_solver *solver,
  const kls_supernode_consumer_run_info *run,
  void *context) {
  kls_supernode_consumer_plan_fill_context *ctx =
    (kls_supernode_consumer_plan_fill_context *)context;
  if (solver == NULL || run == NULL || ctx == NULL) {
    return 0;
  }
  if (run->panel_start >= solver->n) {
    return 1;
  }
  const UF_long panel = run->panel_start;
  const UF_long dst = ctx->cursor[panel]++;
  if (dst >= ctx->plan_ptr[panel + 1u]) {
    return 0;
  }
  ctx->plan_current[dst] = run->current_global;
  ctx->plan_dep[dst] = run->dep_global;
  ctx->plan_rows[dst] = run->run_rows;
  if (run->dep_global < panel) {
    return 0;
  }
  ctx->plan_panel_start[dst] = panel;
  ctx->plan_panel_offset[dst] = run->dep_global - panel;
  const UF_long col_dst = ctx->column_cursor[run->current_global]++;
  if (col_dst >= ctx->column_ptr[run->current_global + 1u]) {
    return 0;
  }
  ctx->column_runs[col_dst] = dst;
  return 1;
}

static int kls_count_supernode_consumer_plan_shape_batches(
  const UF_long *plan_ptr,
  const UF_long *plan_rows,
  const UF_long *plan_panel_offset,
  UF_long n,
  UF_long run_count,
  UF_long max_panel_runs,
  UF_long *shape_batch_count_out,
  UF_long *shape_batch_run_count_out,
  UF_long *shape_batch_run_rows_out,
  UF_long *shape_batch_small_run_count_out,
  UF_long *shape_batch_small_run_rows_out,
  UF_long *shape_batch_max_runs_out) {
  if (shape_batch_count_out != NULL) {
    *shape_batch_count_out = 0u;
  }
  if (shape_batch_run_count_out != NULL) {
    *shape_batch_run_count_out = 0u;
  }
  if (shape_batch_run_rows_out != NULL) {
    *shape_batch_run_rows_out = 0u;
  }
  if (shape_batch_small_run_count_out != NULL) {
    *shape_batch_small_run_count_out = 0u;
  }
  if (shape_batch_small_run_rows_out != NULL) {
    *shape_batch_small_run_rows_out = 0u;
  }
  if (shape_batch_max_runs_out != NULL) {
    *shape_batch_max_runs_out = 0u;
  }
  if (plan_ptr == NULL || plan_rows == NULL ||
      plan_panel_offset == NULL ||
      shape_batch_count_out == NULL ||
      shape_batch_run_count_out == NULL ||
      shape_batch_run_rows_out == NULL ||
      shape_batch_small_run_count_out == NULL ||
      shape_batch_small_run_rows_out == NULL ||
      shape_batch_max_runs_out == NULL) {
    return 0;
  }
  if (run_count == 0u || max_panel_runs < 2u) {
    return 1;
  }
  const size_t max_runs = (size_t)max_panel_runs;
  if ((UF_long)max_runs != max_panel_runs ||
      max_runs > SIZE_MAX / 2u) {
    return 0;
  }
  size_t bucket_count = 4u;
  const size_t wanted_buckets = max_runs * 2u;
  while (bucket_count < wanted_buckets) {
    if (bucket_count > SIZE_MAX / 2u) {
      return 0;
    }
    bucket_count *= 2u;
  }
  if (bucket_count > SIZE_MAX / sizeof(UF_long) ||
      bucket_count > SIZE_MAX / sizeof(unsigned char)) {
    return 0;
  }

  UF_long *bucket_offset =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_offset));
  UF_long *bucket_rows =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_rows));
  UF_long *bucket_count_runs =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_count_runs));
  UF_long *bucket_row_sum =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_row_sum));
  UF_long *bucket_small_count =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_small_count));
  UF_long *bucket_small_rows =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_small_rows));
  unsigned char *bucket_used =
    (unsigned char *)malloc(bucket_count * sizeof(*bucket_used));
  if (bucket_offset == NULL || bucket_rows == NULL ||
      bucket_count_runs == NULL || bucket_row_sum == NULL ||
      bucket_small_count == NULL || bucket_small_rows == NULL ||
      bucket_used == NULL) {
    free(bucket_offset);
    free(bucket_rows);
    free(bucket_count_runs);
    free(bucket_row_sum);
    free(bucket_small_count);
    free(bucket_small_rows);
    free(bucket_used);
    return 0;
  }

  UF_long shape_batch_count = 0u;
  UF_long shape_batch_run_count = 0u;
  UF_long shape_batch_run_rows = 0u;
  UF_long shape_batch_small_run_count = 0u;
  UF_long shape_batch_small_run_rows = 0u;
  UF_long shape_batch_max_runs = 0u;
  for (UF_long panel = 0u; panel < n; ++panel) {
    const UF_long begin = plan_ptr[panel];
    const UF_long end = plan_ptr[panel + 1u];
    if (begin > end || end > run_count) {
      free(bucket_offset);
      free(bucket_rows);
      free(bucket_count_runs);
      free(bucket_row_sum);
      free(bucket_small_count);
      free(bucket_small_rows);
      free(bucket_used);
      return 0;
    }
    const UF_long runs = end - begin;
    if (runs < 2u) {
      continue;
    }
    const size_t panel_runs = (size_t)runs;
    if ((UF_long)panel_runs != runs || panel_runs > max_runs ||
        panel_runs > SIZE_MAX / 2u) {
      free(bucket_offset);
      free(bucket_rows);
      free(bucket_count_runs);
      free(bucket_row_sum);
      free(bucket_small_count);
      free(bucket_small_rows);
      free(bucket_used);
      return 0;
    }
    size_t active_buckets = 4u;
    const size_t wanted = panel_runs * 2u;
    while (active_buckets < wanted) {
      active_buckets *= 2u;
    }
    memset(bucket_used, 0, active_buckets * sizeof(*bucket_used));
    for (UF_long run = begin; run < end; ++run) {
      const UF_long offset = plan_panel_offset[run];
      const UF_long rows = plan_rows[run];
      const uint64_t mixed =
        kls_mix_u64((uint64_t)offset ^
                    (kls_mix_u64((uint64_t)rows) +
                     UINT64_C(0x9e3779b97f4a7c15)));
      size_t slot = (size_t)mixed & (active_buckets - 1u);
      while (bucket_used[slot] &&
             (bucket_offset[slot] != offset ||
              bucket_rows[slot] != rows)) {
        slot = (slot + 1u) & (active_buckets - 1u);
      }
      if (!bucket_used[slot]) {
        bucket_used[slot] = 1u;
        bucket_offset[slot] = offset;
        bucket_rows[slot] = rows;
        bucket_count_runs[slot] = 0u;
        bucket_row_sum[slot] = 0u;
        bucket_small_count[slot] = 0u;
        bucket_small_rows[slot] = 0u;
      }
      if (bucket_count_runs[slot] == UF_long_max ||
          rows > UF_long_max - bucket_row_sum[slot]) {
        free(bucket_offset);
        free(bucket_rows);
        free(bucket_count_runs);
        free(bucket_row_sum);
        free(bucket_small_count);
        free(bucket_small_rows);
        free(bucket_used);
        return 0;
      }
      bucket_count_runs[slot]++;
      bucket_row_sum[slot] += rows;
      if (rows < KLS_EGRAPH_RAGGED_U_SUPERNODE_MIN_ROWS) {
        if (bucket_small_count[slot] == UF_long_max ||
            rows > UF_long_max - bucket_small_rows[slot]) {
          free(bucket_offset);
          free(bucket_rows);
          free(bucket_count_runs);
          free(bucket_row_sum);
          free(bucket_small_count);
          free(bucket_small_rows);
          free(bucket_used);
          return 0;
        }
        bucket_small_count[slot]++;
        bucket_small_rows[slot] += rows;
      }
    }
    for (size_t slot = 0u; slot < active_buckets; ++slot) {
      if (!bucket_used[slot] || bucket_count_runs[slot] < 2u) {
        continue;
      }
      if (shape_batch_count == UF_long_max ||
          bucket_count_runs[slot] > UF_long_max - shape_batch_run_count ||
          bucket_row_sum[slot] > UF_long_max - shape_batch_run_rows ||
          bucket_small_count[slot] >
            UF_long_max - shape_batch_small_run_count ||
          bucket_small_rows[slot] >
            UF_long_max - shape_batch_small_run_rows) {
        free(bucket_offset);
        free(bucket_rows);
        free(bucket_count_runs);
        free(bucket_row_sum);
        free(bucket_small_count);
        free(bucket_small_rows);
        free(bucket_used);
        return 0;
      }
      shape_batch_count++;
      shape_batch_run_count += bucket_count_runs[slot];
      shape_batch_run_rows += bucket_row_sum[slot];
      shape_batch_small_run_count += bucket_small_count[slot];
      shape_batch_small_run_rows += bucket_small_rows[slot];
      if (bucket_count_runs[slot] > shape_batch_max_runs) {
        shape_batch_max_runs = bucket_count_runs[slot];
      }
    }
  }

  free(bucket_offset);
  free(bucket_rows);
  free(bucket_count_runs);
  free(bucket_row_sum);
  free(bucket_small_count);
  free(bucket_small_rows);
  free(bucket_used);
  *shape_batch_count_out = shape_batch_count;
  *shape_batch_run_count_out = shape_batch_run_count;
  *shape_batch_run_rows_out = shape_batch_run_rows;
  *shape_batch_small_run_count_out = shape_batch_small_run_count;
  *shape_batch_small_run_rows_out = shape_batch_small_run_rows;
  *shape_batch_max_runs_out = shape_batch_max_runs;
  return 1;
}

static void kls_free_supernode_consumer_plan_shape_groups(
  UF_long *group_ptr,
  UF_long *group_runs,
  UF_long *group_panel_start,
  UF_long *group_panel_offset,
  UF_long *group_rows) {
  free(group_ptr);
  free(group_runs);
  free(group_panel_start);
  free(group_panel_offset);
  free(group_rows);
}

static int kls_count_supernode_consumer_plan_column_shape_batches(
  const UF_long *column_ptr,
  const UF_long *column_runs,
  const UF_long *plan_panel_start,
  const UF_long *plan_panel_offset,
  const UF_long *plan_rows,
  UF_long n,
  UF_long run_count,
  UF_long max_column_runs,
  UF_long *shape_batch_count_out,
  UF_long *shape_batch_run_count_out,
  UF_long *shape_batch_run_rows_out,
  UF_long *shape_batch_small_run_count_out,
  UF_long *shape_batch_small_run_rows_out,
  UF_long *shape_batch_max_runs_out) {
  if (shape_batch_count_out != NULL) {
    *shape_batch_count_out = 0u;
  }
  if (shape_batch_run_count_out != NULL) {
    *shape_batch_run_count_out = 0u;
  }
  if (shape_batch_run_rows_out != NULL) {
    *shape_batch_run_rows_out = 0u;
  }
  if (shape_batch_small_run_count_out != NULL) {
    *shape_batch_small_run_count_out = 0u;
  }
  if (shape_batch_small_run_rows_out != NULL) {
    *shape_batch_small_run_rows_out = 0u;
  }
  if (shape_batch_max_runs_out != NULL) {
    *shape_batch_max_runs_out = 0u;
  }
  if (column_ptr == NULL || column_runs == NULL ||
      plan_panel_start == NULL || plan_panel_offset == NULL ||
      plan_rows == NULL ||
      shape_batch_count_out == NULL ||
      shape_batch_run_count_out == NULL ||
      shape_batch_run_rows_out == NULL ||
      shape_batch_small_run_count_out == NULL ||
      shape_batch_small_run_rows_out == NULL ||
      shape_batch_max_runs_out == NULL) {
    return 0;
  }
  if (run_count == 0u || max_column_runs < 2u) {
    return 1;
  }
  const size_t max_runs = (size_t)max_column_runs;
  if ((UF_long)max_runs != max_column_runs ||
      max_runs > SIZE_MAX / 2u) {
    return 0;
  }

  size_t bucket_count = 4u;
  const size_t wanted_buckets = max_runs * 2u;
  while (bucket_count < wanted_buckets) {
    if (bucket_count > SIZE_MAX / 2u) {
      return 0;
    }
    bucket_count *= 2u;
  }
  if (bucket_count > SIZE_MAX / sizeof(UF_long) ||
      bucket_count > SIZE_MAX / sizeof(unsigned char)) {
    return 0;
  }

  UF_long *bucket_panel_start =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_panel_start));
  UF_long *bucket_offset =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_offset));
  UF_long *bucket_rows =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_rows));
  UF_long *bucket_count_runs =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_count_runs));
  UF_long *bucket_row_sum =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_row_sum));
  UF_long *bucket_small_count =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_small_count));
  UF_long *bucket_small_rows =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_small_rows));
  unsigned char *bucket_used =
    (unsigned char *)malloc(bucket_count * sizeof(*bucket_used));
  if (bucket_panel_start == NULL || bucket_offset == NULL ||
      bucket_rows == NULL || bucket_count_runs == NULL ||
      bucket_row_sum == NULL || bucket_small_count == NULL ||
      bucket_small_rows == NULL || bucket_used == NULL) {
    free(bucket_panel_start);
    free(bucket_offset);
    free(bucket_rows);
    free(bucket_count_runs);
    free(bucket_row_sum);
    free(bucket_small_count);
    free(bucket_small_rows);
    free(bucket_used);
    return 0;
  }

  UF_long shape_batch_count = 0u;
  UF_long shape_batch_run_count = 0u;
  UF_long shape_batch_run_rows = 0u;
  UF_long shape_batch_small_run_count = 0u;
  UF_long shape_batch_small_run_rows = 0u;
  UF_long shape_batch_max_runs = 0u;
  int ok = 1;
  for (UF_long current = 0u; ok && current < n; ++current) {
    const UF_long begin = column_ptr[current];
    const UF_long end = column_ptr[current + 1u];
    if (begin > end || end > run_count) {
      ok = 0;
      break;
    }
    const UF_long runs = end - begin;
    if (runs < 2u) {
      continue;
    }
    const size_t column_run_count = (size_t)runs;
    if ((UF_long)column_run_count != runs || column_run_count > max_runs ||
        column_run_count > SIZE_MAX / 2u) {
      ok = 0;
      break;
    }
    size_t active_buckets = 4u;
    const size_t wanted = column_run_count * 2u;
    while (active_buckets < wanted) {
      active_buckets *= 2u;
    }
    memset(bucket_used, 0, active_buckets * sizeof(*bucket_used));
    for (UF_long pos = begin; ok && pos < end; ++pos) {
      const UF_long run = column_runs[pos];
      if (run >= run_count) {
        ok = 0;
        break;
      }
      const UF_long panel_start = plan_panel_start[run];
      const UF_long offset = plan_panel_offset[run];
      const UF_long rows = plan_rows[run];
      const uint64_t mixed =
        kls_mix_u64((uint64_t)panel_start ^
                    (kls_mix_u64((uint64_t)offset) +
                     UINT64_C(0x9e3779b97f4a7c15)) ^
                    (kls_mix_u64((uint64_t)rows) +
                     UINT64_C(0xbf58476d1ce4e5b9)));
      size_t slot = (size_t)mixed & (active_buckets - 1u);
      while (bucket_used[slot] &&
             (bucket_panel_start[slot] != panel_start ||
              bucket_offset[slot] != offset ||
              bucket_rows[slot] != rows)) {
        slot = (slot + 1u) & (active_buckets - 1u);
      }
      if (!bucket_used[slot]) {
        bucket_used[slot] = 1u;
        bucket_panel_start[slot] = panel_start;
        bucket_offset[slot] = offset;
        bucket_rows[slot] = rows;
        bucket_count_runs[slot] = 0u;
        bucket_row_sum[slot] = 0u;
        bucket_small_count[slot] = 0u;
        bucket_small_rows[slot] = 0u;
      }
      if (bucket_count_runs[slot] == UF_long_max ||
          rows > UF_long_max - bucket_row_sum[slot]) {
        ok = 0;
        break;
      }
      bucket_count_runs[slot]++;
      bucket_row_sum[slot] += rows;
      if (rows < KLS_EGRAPH_RAGGED_U_SUPERNODE_MIN_ROWS) {
        if (bucket_small_count[slot] == UF_long_max ||
            rows > UF_long_max - bucket_small_rows[slot]) {
          ok = 0;
          break;
        }
        bucket_small_count[slot]++;
        bucket_small_rows[slot] += rows;
      }
    }
    for (size_t slot = 0u; ok && slot < active_buckets; ++slot) {
      if (!bucket_used[slot] || bucket_count_runs[slot] < 2u) {
        continue;
      }
      if (shape_batch_count == UF_long_max ||
          bucket_count_runs[slot] > UF_long_max - shape_batch_run_count ||
          bucket_row_sum[slot] > UF_long_max - shape_batch_run_rows ||
          bucket_small_count[slot] >
            UF_long_max - shape_batch_small_run_count ||
          bucket_small_rows[slot] >
            UF_long_max - shape_batch_small_run_rows) {
        ok = 0;
        break;
      }
      shape_batch_count++;
      shape_batch_run_count += bucket_count_runs[slot];
      shape_batch_run_rows += bucket_row_sum[slot];
      shape_batch_small_run_count += bucket_small_count[slot];
      shape_batch_small_run_rows += bucket_small_rows[slot];
      if (bucket_count_runs[slot] > shape_batch_max_runs) {
        shape_batch_max_runs = bucket_count_runs[slot];
      }
    }
  }

  free(bucket_panel_start);
  free(bucket_offset);
  free(bucket_rows);
  free(bucket_count_runs);
  free(bucket_row_sum);
  free(bucket_small_count);
  free(bucket_small_rows);
  free(bucket_used);
  if (!ok) {
    return 0;
  }
  *shape_batch_count_out = shape_batch_count;
  *shape_batch_run_count_out = shape_batch_run_count;
  *shape_batch_run_rows_out = shape_batch_run_rows;
  *shape_batch_small_run_count_out = shape_batch_small_run_count;
  *shape_batch_small_run_rows_out = shape_batch_small_run_rows;
  *shape_batch_max_runs_out = shape_batch_max_runs;
  return 1;
}

static int kls_build_supernode_consumer_plan_shape_groups(
  const UF_long *plan_ptr,
  const UF_long *plan_rows,
  const UF_long *plan_panel_offset,
  UF_long n,
  UF_long run_count,
  UF_long max_panel_runs,
  UF_long group_count,
  UF_long group_run_count,
  UF_long **group_ptr_out,
  UF_long **group_runs_out,
  UF_long **group_panel_start_out,
  UF_long **group_panel_offset_out,
  UF_long **group_rows_out) {
  if (group_ptr_out != NULL) {
    *group_ptr_out = NULL;
  }
  if (group_runs_out != NULL) {
    *group_runs_out = NULL;
  }
  if (group_panel_start_out != NULL) {
    *group_panel_start_out = NULL;
  }
  if (group_panel_offset_out != NULL) {
    *group_panel_offset_out = NULL;
  }
  if (group_rows_out != NULL) {
    *group_rows_out = NULL;
  }
  if (plan_ptr == NULL || plan_rows == NULL ||
      plan_panel_offset == NULL ||
      group_ptr_out == NULL || group_runs_out == NULL ||
      group_panel_start_out == NULL ||
      group_panel_offset_out == NULL || group_rows_out == NULL) {
    return 0;
  }
  if (group_count == 0u) {
    return group_run_count == 0u;
  }
  if (run_count == 0u || max_panel_runs < 2u ||
      group_run_count < group_count) {
    return 0;
  }
  const size_t group_count_size = (size_t)group_count;
  const size_t group_run_count_size = (size_t)group_run_count;
  const size_t max_runs = (size_t)max_panel_runs;
  if ((UF_long)group_count_size != group_count ||
      (UF_long)group_run_count_size != group_run_count ||
      (UF_long)max_runs != max_panel_runs ||
      group_count_size > SIZE_MAX - 1u ||
      group_count_size > SIZE_MAX / sizeof(UF_long) ||
      group_run_count_size > SIZE_MAX / sizeof(UF_long) ||
      max_runs > SIZE_MAX / 2u) {
    return 0;
  }

  size_t bucket_count = 4u;
  const size_t wanted_buckets = max_runs * 2u;
  while (bucket_count < wanted_buckets) {
    if (bucket_count > SIZE_MAX / 2u) {
      return 0;
    }
    bucket_count *= 2u;
  }
  if (bucket_count > SIZE_MAX / sizeof(UF_long) ||
      bucket_count > SIZE_MAX / sizeof(unsigned char)) {
    return 0;
  }

  UF_long *group_ptr =
    (UF_long *)malloc((group_count_size + 1u) * sizeof(*group_ptr));
  UF_long *group_runs =
    (UF_long *)malloc(group_run_count_size * sizeof(*group_runs));
  UF_long *group_panel_start =
    (UF_long *)malloc(group_count_size * sizeof(*group_panel_start));
  UF_long *group_panel_offset =
    (UF_long *)malloc(group_count_size * sizeof(*group_panel_offset));
  UF_long *group_rows =
    (UF_long *)malloc(group_count_size * sizeof(*group_rows));
  UF_long *bucket_offset =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_offset));
  UF_long *bucket_rows =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_rows));
  UF_long *bucket_count_runs =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_count_runs));
  unsigned char *bucket_used =
    (unsigned char *)malloc(bucket_count * sizeof(*bucket_used));
  if (group_ptr == NULL || group_runs == NULL ||
      group_panel_start == NULL || group_panel_offset == NULL ||
      group_rows == NULL || bucket_offset == NULL ||
      bucket_rows == NULL || bucket_count_runs == NULL ||
      bucket_used == NULL) {
    kls_free_supernode_consumer_plan_shape_groups(
      group_ptr, group_runs, group_panel_start, group_panel_offset,
      group_rows);
    free(bucket_offset);
    free(bucket_rows);
    free(bucket_count_runs);
    free(bucket_used);
    return 0;
  }

  UF_long group_pos = 0u;
  UF_long run_pos = 0u;
  for (UF_long panel = 0u; panel < n; ++panel) {
    const UF_long begin = plan_ptr[panel];
    const UF_long end = plan_ptr[panel + 1u];
    if (begin > end || end > run_count) {
      kls_free_supernode_consumer_plan_shape_groups(
        group_ptr, group_runs, group_panel_start, group_panel_offset,
        group_rows);
      free(bucket_offset);
      free(bucket_rows);
      free(bucket_count_runs);
      free(bucket_used);
      return 0;
    }
    const UF_long runs = end - begin;
    if (runs < 2u) {
      continue;
    }
    const size_t panel_runs = (size_t)runs;
    if ((UF_long)panel_runs != runs || panel_runs > max_runs ||
        panel_runs > SIZE_MAX / 2u) {
      kls_free_supernode_consumer_plan_shape_groups(
        group_ptr, group_runs, group_panel_start, group_panel_offset,
        group_rows);
      free(bucket_offset);
      free(bucket_rows);
      free(bucket_count_runs);
      free(bucket_used);
      return 0;
    }
    size_t active_buckets = 4u;
    const size_t wanted = panel_runs * 2u;
    while (active_buckets < wanted) {
      active_buckets *= 2u;
    }
    memset(bucket_used, 0, active_buckets * sizeof(*bucket_used));
    for (UF_long run = begin; run < end; ++run) {
      const UF_long offset = plan_panel_offset[run];
      const UF_long rows = plan_rows[run];
      const uint64_t mixed =
        kls_mix_u64((uint64_t)offset ^
                    (kls_mix_u64((uint64_t)rows) +
                     UINT64_C(0x9e3779b97f4a7c15)));
      size_t slot = (size_t)mixed & (active_buckets - 1u);
      while (bucket_used[slot] &&
             (bucket_offset[slot] != offset ||
              bucket_rows[slot] != rows)) {
        slot = (slot + 1u) & (active_buckets - 1u);
      }
      if (!bucket_used[slot]) {
        bucket_used[slot] = 1u;
        bucket_offset[slot] = offset;
        bucket_rows[slot] = rows;
        bucket_count_runs[slot] = 0u;
      }
      if (bucket_count_runs[slot] == UF_long_max) {
        kls_free_supernode_consumer_plan_shape_groups(
          group_ptr, group_runs, group_panel_start, group_panel_offset,
          group_rows);
        free(bucket_offset);
        free(bucket_rows);
        free(bucket_count_runs);
        free(bucket_used);
        return 0;
      }
      bucket_count_runs[slot]++;
    }
    for (size_t slot = 0u; slot < active_buckets; ++slot) {
      if (!bucket_used[slot] || bucket_count_runs[slot] < 2u) {
        continue;
      }
      if (group_pos >= group_count ||
          run_pos > group_run_count ||
          bucket_count_runs[slot] > group_run_count - run_pos) {
        kls_free_supernode_consumer_plan_shape_groups(
          group_ptr, group_runs, group_panel_start, group_panel_offset,
          group_rows);
        free(bucket_offset);
        free(bucket_rows);
        free(bucket_count_runs);
        free(bucket_used);
        return 0;
      }
      const UF_long offset = bucket_offset[slot];
      const UF_long rows = bucket_rows[slot];
      group_ptr[group_pos] = run_pos;
      group_panel_start[group_pos] = panel;
      group_panel_offset[group_pos] = offset;
      group_rows[group_pos] = rows;
      UF_long copied = 0u;
      for (UF_long run = begin; run < end; ++run) {
        if (plan_panel_offset[run] == offset && plan_rows[run] == rows) {
          if (run_pos >= group_run_count) {
            kls_free_supernode_consumer_plan_shape_groups(
              group_ptr, group_runs, group_panel_start, group_panel_offset,
              group_rows);
            free(bucket_offset);
            free(bucket_rows);
            free(bucket_count_runs);
            free(bucket_used);
            return 0;
          }
          group_runs[run_pos++] = run;
          copied++;
        }
      }
      if (copied != bucket_count_runs[slot]) {
        kls_free_supernode_consumer_plan_shape_groups(
          group_ptr, group_runs, group_panel_start, group_panel_offset,
          group_rows);
        free(bucket_offset);
        free(bucket_rows);
        free(bucket_count_runs);
        free(bucket_used);
        return 0;
      }
      group_pos++;
    }
  }
  if (group_pos != group_count || run_pos != group_run_count) {
    kls_free_supernode_consumer_plan_shape_groups(
      group_ptr, group_runs, group_panel_start, group_panel_offset,
      group_rows);
    free(bucket_offset);
    free(bucket_rows);
    free(bucket_count_runs);
    free(bucket_used);
    return 0;
  }
  group_ptr[group_count] = group_run_count;

  free(bucket_offset);
  free(bucket_rows);
  free(bucket_count_runs);
  free(bucket_used);
  *group_ptr_out = group_ptr;
  *group_runs_out = group_runs;
  *group_panel_start_out = group_panel_start;
  *group_panel_offset_out = group_panel_offset;
  *group_rows_out = group_rows;
  return 1;
}

static int kls_supernode_consumer_plan_run_dep_position(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  UF_long run,
  UF_long *position_out,
  UF_long *block_start_out,
  const UF_long **u_indices_out) {
  if (position_out != NULL) {
    *position_out = 0u;
  }
  if (block_start_out != NULL) {
    *block_start_out = 0u;
  }
  if (u_indices_out != NULL) {
    *u_indices_out = NULL;
  }
  if (solver == NULL || plan_current == NULL || plan_dep == NULL ||
      run >= run_count || solver->symbolic == NULL ||
      solver->numeric == NULL || solver->symbolic->R == NULL ||
      solver->numeric->LUbx == NULL || solver->numeric->Uip == NULL ||
      solver->numeric->Ulen == NULL || position_out == NULL) {
    return 0;
  }
  const UF_long current = plan_current[run];
  const UF_long dep = plan_dep[run];
  if (current >= solver->n || dep >= current || dep >= solver->n) {
    return 0;
  }

  UF_long block = KLS_KLU_EMPTY;
  if (solver->symbolic->nblocks == 1u) {
    block = 0u;
  } else if (solver->refactor_col_block != NULL) {
    block = solver->refactor_col_block[current];
  } else {
    block = kls_block_for_pivot(solver, current);
  }
  if (block == KLS_KLU_EMPTY || block >= solver->symbolic->nblocks) {
    return 0;
  }
  const UF_long k1 = solver->symbolic->R[block];
  const UF_long k2 = solver->symbolic->R[block + 1u];
  if (current < k1 || current >= k2) {
    return 0;
  }
  if (dep < k1 || dep >= k2) {
    return 0;
  }
  const UF_long local_current = current - k1;
  const UF_long local_dep = dep - k1;
  if (local_current == 0u || solver->numeric->Ulen[current] == 0u) {
    return 0;
  }
  if (local_dep >= local_current) {
    return 0;
  }
  double *lu = (double *)solver->numeric->LUbx[block];
  if (lu == NULL) {
    return 0;
  }
  const UF_long *uip = solver->numeric->Uip + k1;
  const UF_long *ulen = solver->numeric->Ulen + k1;
  UF_long *ui = NULL;
  double *ux = NULL;
  UF_long ucol_len = 0u;
  kls_klu_get_pointer(lu, uip, ulen, local_current, &ui, &ux, &ucol_len);
  (void)ux;
  if (ui == NULL && ucol_len > 0u) {
    return 0;
  }
  for (UF_long pos = 0u; pos < ucol_len; ++pos) {
    if (ui[pos] == local_dep) {
      *position_out = pos;
      if (block_start_out != NULL) {
        *block_start_out = k1;
      }
      if (u_indices_out != NULL) {
        *u_indices_out = ui;
      }
      return 1;
    }
  }
  return 0;
}

static int kls_supernode_consumer_plan_run_is_first_dependency(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  UF_long run) {
  UF_long position = 0u;
  if (!kls_supernode_consumer_plan_run_dep_position(
        solver, plan_current, plan_dep, run_count, run, &position, NULL,
        NULL)) {
    return 0;
  }
  return position == 0u;
}

static int kls_supernode_consumer_plan_run_advance_cost(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  UF_long run,
  UF_long *advance_deps_out,
  double *advance_work_out) {
  if (advance_deps_out != NULL) {
    *advance_deps_out = 0u;
  }
  if (advance_work_out != NULL) {
    *advance_work_out = 0.0;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Llen == NULL || solver->numeric->Ulen == NULL ||
      advance_deps_out == NULL ||
      advance_work_out == NULL) {
    return 0;
  }

  UF_long position = 0u;
  UF_long block_start = 0u;
  const UF_long *ui = NULL;
  if (!kls_supernode_consumer_plan_run_dep_position(
        solver, plan_current, plan_dep, run_count, run, &position,
        &block_start, &ui)) {
    return 0;
  }
  const UF_long current = plan_current[run];

  double work = 0.0;
  for (UF_long pos = 0u; pos < position; ++pos) {
    const UF_long dep = block_start + ui[pos];
    if (dep >= solver->n || dep >= current) {
      return 0;
    }
    work += 1.0 + (double)solver->numeric->Llen[dep];
  }
  *advance_deps_out = position;
  *advance_work_out = work;
  return 1;
}

static int kls_supernode_consumer_plan_run_suffix_cost(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  UF_long run,
  UF_long advance_deps,
  UF_long prefix_rows,
  UF_long *suffix_deps_out,
  UF_long *suffix_update_entries_out) {
  if (suffix_deps_out != NULL) {
    *suffix_deps_out = 0u;
  }
  if (suffix_update_entries_out != NULL) {
    *suffix_update_entries_out = 0u;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Llen == NULL || solver->numeric->Ulen == NULL ||
      plan_current == NULL || plan_dep == NULL ||
      suffix_deps_out == NULL || suffix_update_entries_out == NULL) {
    return 0;
  }

  UF_long position = 0u;
  UF_long block_start = 0u;
  const UF_long *ui = NULL;
  if (!kls_supernode_consumer_plan_run_dep_position(
        solver, plan_current, plan_dep, run_count, run, &position,
        &block_start, &ui) ||
      position != advance_deps) {
    return 0;
  }
  const UF_long current = plan_current[run];
  if (current >= solver->n) {
    return 0;
  }
  const UF_long ulen = solver->numeric->Ulen[current];
  if ((ulen > 0u && ui == NULL) ||
      advance_deps > ulen ||
      prefix_rows > ulen - advance_deps) {
    return 0;
  }
  const UF_long suffix_begin = advance_deps + prefix_rows;
  const UF_long suffix_deps = ulen - suffix_begin;
  UF_long suffix_update_entries = 0u;
  for (UF_long pos = suffix_begin; pos < ulen; ++pos) {
    const UF_long local_dep = ui[pos];
    if (local_dep > UF_long_max - block_start) {
      return 0;
    }
    const UF_long dep = block_start + local_dep;
    if (dep >= solver->n || dep >= current) {
      return 0;
    }
    const UF_long llen = solver->numeric->Llen[dep];
    if (llen == UF_long_max ||
        suffix_update_entries > UF_long_max - 1u - llen) {
      return 0;
    }
    suffix_update_entries += 1u + llen;
  }

  *suffix_deps_out = suffix_deps;
  *suffix_update_entries_out = suffix_update_entries;
  return 1;
}

static int kls_count_refactor_algorithm5_payoff_group_suffix_sharing(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  const UF_long *selected_runs,
  const UF_long *group_ptr,
  UF_long group_count,
  const UF_long *run_advance_deps,
  const UF_long *run_prefix_rows,
  UF_long *unique_deps_total_out,
  UF_long *duplicate_deps_total_out,
  UF_long *shared_deps_total_out,
  UF_long *max_dep_fanout_out,
  UF_long *duplicate_update_entries_total_out) {
  if (unique_deps_total_out != NULL) {
    *unique_deps_total_out = 0u;
  }
  if (duplicate_deps_total_out != NULL) {
    *duplicate_deps_total_out = 0u;
  }
  if (shared_deps_total_out != NULL) {
    *shared_deps_total_out = 0u;
  }
  if (max_dep_fanout_out != NULL) {
    *max_dep_fanout_out = 0u;
  }
  if (duplicate_update_entries_total_out != NULL) {
    *duplicate_update_entries_total_out = 0u;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Ulen == NULL || solver->numeric->Llen == NULL ||
      plan_current == NULL || plan_dep == NULL ||
      unique_deps_total_out == NULL ||
      duplicate_deps_total_out == NULL ||
      shared_deps_total_out == NULL ||
      max_dep_fanout_out == NULL ||
      duplicate_update_entries_total_out == NULL) {
    return 0;
  }
  if (group_count == 0u) {
    return 1;
  }
  if (selected_runs == NULL || group_ptr == NULL ||
      run_advance_deps == NULL || run_prefix_rows == NULL) {
    return 0;
  }
  const size_t n = (size_t)solver->n;
  if ((UF_long)n != solver->n || n > SIZE_MAX / sizeof(UF_long)) {
    return 0;
  }
  const size_t n_alloc = n > 0u ? n : 1u;
  UF_long *stamp_workspace =
    (UF_long *)calloc(n_alloc, sizeof(*stamp_workspace));
  UF_long *fanout_workspace =
    (UF_long *)calloc(n_alloc, sizeof(*fanout_workspace));
  if (stamp_workspace == NULL || fanout_workspace == NULL) {
    free(stamp_workspace);
    free(fanout_workspace);
    return 0;
  }

  const UF_long selected_run_count = group_ptr[group_count];
  UF_long stamp_value = 0u;
  UF_long unique_total = 0u;
  UF_long duplicate_total = 0u;
  UF_long shared_total = 0u;
  UF_long max_fanout = 0u;
  UF_long duplicate_update_total = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    if (begin > end || end > selected_run_count) {
      free(stamp_workspace);
      free(fanout_workspace);
      return 0;
    }
    stamp_value++;
    if (stamp_value == 0u) {
      memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
      stamp_value = 1u;
    }
    const UF_long stamp = stamp_value;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = selected_runs[pos];
      if (run >= run_count) {
        free(stamp_workspace);
        free(fanout_workspace);
        return 0;
      }
      UF_long dep_pos = 0u;
      UF_long block_start = 0u;
      const UF_long *ui = NULL;
      if (!kls_supernode_consumer_plan_run_dep_position(
            solver, plan_current, plan_dep, run_count, run, &dep_pos,
            &block_start, &ui)) {
        free(stamp_workspace);
        free(fanout_workspace);
        return 0;
      }
      const UF_long current = plan_current[run];
      if (current >= solver->n || solver->numeric->Ulen[current] < dep_pos) {
        free(stamp_workspace);
        free(fanout_workspace);
        return 0;
      }
      const UF_long ulen = solver->numeric->Ulen[current];
      if (ulen > 0u && ui == NULL) {
        free(stamp_workspace);
        free(fanout_workspace);
        return 0;
      }
      const UF_long advance_deps = run_advance_deps[run];
      const UF_long prefix_rows = run_prefix_rows[run];
      if (advance_deps != dep_pos ||
          advance_deps > ulen ||
          prefix_rows > ulen - advance_deps) {
        free(stamp_workspace);
        free(fanout_workspace);
        return 0;
      }
      const UF_long suffix_begin = advance_deps + prefix_rows;
      for (UF_long up = suffix_begin; up < ulen; ++up) {
        const UF_long local_dep = ui[up];
        if (local_dep > UF_long_max - block_start) {
          free(stamp_workspace);
          free(fanout_workspace);
          return 0;
        }
        const UF_long dep = block_start + local_dep;
        if (dep >= solver->n || dep >= current) {
          free(stamp_workspace);
          free(fanout_workspace);
          return 0;
        }
        if (solver->numeric->Llen[dep] == UF_long_max) {
          free(stamp_workspace);
          free(fanout_workspace);
          return 0;
        }
        const UF_long update_entries = 1u + solver->numeric->Llen[dep];
        if (stamp_workspace[dep] != stamp) {
          if (unique_total == UF_long_max) {
            free(stamp_workspace);
            free(fanout_workspace);
            return 0;
          }
          stamp_workspace[dep] = stamp;
          fanout_workspace[dep] = 1u;
          unique_total++;
          if (max_fanout == 0u) {
            max_fanout = 1u;
          }
          continue;
        }
        if (fanout_workspace[dep] == UF_long_max ||
            duplicate_total == UF_long_max ||
            duplicate_update_total > UF_long_max - update_entries) {
          free(stamp_workspace);
          free(fanout_workspace);
          return 0;
        }
        fanout_workspace[dep]++;
        duplicate_total++;
        duplicate_update_total += update_entries;
        if (fanout_workspace[dep] == 2u) {
          if (shared_total == UF_long_max) {
            free(stamp_workspace);
            free(fanout_workspace);
            return 0;
          }
          shared_total++;
        }
        if (fanout_workspace[dep] > max_fanout) {
          max_fanout = fanout_workspace[dep];
        }
      }
    }
  }

  free(stamp_workspace);
  free(fanout_workspace);
  *unique_deps_total_out = unique_total;
  *duplicate_deps_total_out = duplicate_total;
  *shared_deps_total_out = shared_total;
  *max_dep_fanout_out = max_fanout;
  *duplicate_update_entries_total_out = duplicate_update_total;
  return 1;
}

static int kls_refactor_algorithm5_payoff_run_suffix_pattern(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  UF_long run,
  const UF_long *run_advance_deps,
  const UF_long *run_prefix_rows,
  UF_long *suffix_begin_out,
  UF_long *ulen_out,
  UF_long *block_start_out,
  const UF_long **ui_out) {
  if (suffix_begin_out != NULL) {
    *suffix_begin_out = 0u;
  }
  if (ulen_out != NULL) {
    *ulen_out = 0u;
  }
  if (block_start_out != NULL) {
    *block_start_out = 0u;
  }
  if (ui_out != NULL) {
    *ui_out = NULL;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Ulen == NULL || plan_current == NULL ||
      plan_dep == NULL || run_advance_deps == NULL ||
      run_prefix_rows == NULL || suffix_begin_out == NULL ||
      ulen_out == NULL || block_start_out == NULL || ui_out == NULL) {
    return 0;
  }
  UF_long dep_pos = 0u;
  UF_long block_start = 0u;
  const UF_long *ui = NULL;
  if (!kls_supernode_consumer_plan_run_dep_position(
        solver, plan_current, plan_dep, run_count, run, &dep_pos,
        &block_start, &ui)) {
    return 0;
  }
  const UF_long current = plan_current[run];
  if (current >= solver->n || solver->numeric->Ulen[current] < dep_pos) {
    return 0;
  }
  const UF_long ulen = solver->numeric->Ulen[current];
  if (ulen > 0u && ui == NULL) {
    return 0;
  }
  const UF_long advance_deps = run_advance_deps[run];
  const UF_long prefix_rows = run_prefix_rows[run];
  if (advance_deps != dep_pos ||
      advance_deps > ulen ||
      prefix_rows > ulen - advance_deps) {
    return 0;
  }
  *suffix_begin_out = advance_deps + prefix_rows;
  *ulen_out = ulen;
  *block_start_out = block_start;
  *ui_out = ui;
  return 1;
}

static int kls_build_refactor_algorithm5_payoff_group_suffix_map(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  const UF_long *selected_runs,
  const UF_long *group_ptr,
  UF_long group_count,
  const UF_long *run_advance_deps,
  const UF_long *run_prefix_rows,
  UF_long expected_unique_deps_total,
  UF_long expected_run_refs_total,
  UF_long **group_suffix_ptr_out,
  UF_long **group_suffix_cols_out,
  UF_long **group_suffix_run_ptr_out,
  UF_long **group_suffix_runs_out,
  UF_long **group_suffix_up_out) {
  if (group_suffix_ptr_out != NULL) {
    *group_suffix_ptr_out = NULL;
  }
  if (group_suffix_cols_out != NULL) {
    *group_suffix_cols_out = NULL;
  }
  if (group_suffix_run_ptr_out != NULL) {
    *group_suffix_run_ptr_out = NULL;
  }
  if (group_suffix_runs_out != NULL) {
    *group_suffix_runs_out = NULL;
  }
  if (group_suffix_up_out != NULL) {
    *group_suffix_up_out = NULL;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Ulen == NULL || plan_current == NULL ||
      plan_dep == NULL || group_suffix_ptr_out == NULL ||
      group_suffix_cols_out == NULL ||
      group_suffix_run_ptr_out == NULL ||
      group_suffix_runs_out == NULL || group_suffix_up_out == NULL) {
    return 0;
  }
  if (group_count == 0u) {
    return expected_unique_deps_total == 0u && expected_run_refs_total == 0u;
  }
  if (selected_runs == NULL || group_ptr == NULL ||
      run_advance_deps == NULL || run_prefix_rows == NULL) {
    return 0;
  }

  const size_t group_count_size = (size_t)group_count;
  const size_t unique_size = (size_t)expected_unique_deps_total;
  const size_t ref_size = (size_t)expected_run_refs_total;
  const size_t n = (size_t)solver->n;
  if ((UF_long)group_count_size != group_count ||
      (UF_long)unique_size != expected_unique_deps_total ||
      (UF_long)ref_size != expected_run_refs_total ||
      (UF_long)n != solver->n ||
      group_count_size > (SIZE_MAX / sizeof(UF_long)) - 1u ||
      unique_size > (SIZE_MAX / sizeof(UF_long)) - 1u ||
      ref_size > SIZE_MAX / sizeof(UF_long) ||
      n > SIZE_MAX / sizeof(UF_long)) {
    return 0;
  }
  const size_t n_alloc = n > 0u ? n : 1u;

  UF_long *group_suffix_ptr =
    (UF_long *)calloc(group_count_size + 1u, sizeof(*group_suffix_ptr));
  UF_long *stamp_workspace =
    (UF_long *)calloc(n_alloc, sizeof(*stamp_workspace));
  UF_long *entry_workspace =
    (UF_long *)malloc(n_alloc * sizeof(*entry_workspace));
  UF_long *group_suffix_cols = NULL;
  UF_long *group_suffix_run_ptr = NULL;
  UF_long *group_suffix_runs = NULL;
  UF_long *group_suffix_up = NULL;
  UF_long *fill_cursor = NULL;
  if (group_suffix_ptr == NULL || stamp_workspace == NULL ||
      entry_workspace == NULL) {
    goto fail;
  }

  const UF_long selected_run_count = group_ptr[group_count];
  UF_long stamp_value = 0u;
  UF_long counted_unique = 0u;
  UF_long counted_refs = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    if (begin > end || end > selected_run_count) {
      goto fail;
    }
    stamp_value++;
    if (stamp_value == 0u) {
      memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
      stamp_value = 1u;
    }
    const UF_long stamp = stamp_value;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = selected_runs[pos];
      if (run >= run_count) {
        goto fail;
      }
      UF_long suffix_begin = 0u;
      UF_long ulen = 0u;
      UF_long block_start = 0u;
      const UF_long *ui = NULL;
      if (!kls_refactor_algorithm5_payoff_run_suffix_pattern(
            solver, plan_current, plan_dep, run_count, run,
            run_advance_deps, run_prefix_rows, &suffix_begin, &ulen,
            &block_start, &ui)) {
        goto fail;
      }
      const UF_long current = plan_current[run];
      for (UF_long up = suffix_begin; up < ulen; ++up) {
        const UF_long local_dep = ui[up];
        if (local_dep > UF_long_max - block_start ||
            counted_refs == UF_long_max) {
          goto fail;
        }
        const UF_long dep = block_start + local_dep;
        if (dep >= solver->n || dep >= current) {
          goto fail;
        }
        counted_refs++;
        if (stamp_workspace[dep] != stamp) {
          if (counted_unique == UF_long_max ||
              group_suffix_ptr[group + 1u] == UF_long_max) {
            goto fail;
          }
          stamp_workspace[dep] = stamp;
          counted_unique++;
          group_suffix_ptr[group + 1u]++;
        }
      }
    }
  }
  if (counted_unique != expected_unique_deps_total ||
      counted_refs != expected_run_refs_total) {
    goto fail;
  }

  UF_long unique_prefix = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long group_unique = group_suffix_ptr[group + 1u];
    if (group_unique > UF_long_max - unique_prefix) {
      goto fail;
    }
    group_suffix_ptr[group] = unique_prefix;
    unique_prefix += group_unique;
    group_suffix_ptr[group + 1u] = unique_prefix;
  }
  if (unique_prefix != expected_unique_deps_total) {
    goto fail;
  }

  const size_t run_ptr_size = unique_size + 1u;
  group_suffix_cols =
    unique_size > 0u
      ? (UF_long *)malloc(unique_size * sizeof(*group_suffix_cols))
      : NULL;
  group_suffix_run_ptr =
    (UF_long *)calloc(run_ptr_size, sizeof(*group_suffix_run_ptr));
  if ((unique_size > 0u && group_suffix_cols == NULL) ||
      group_suffix_run_ptr == NULL) {
    goto fail;
  }

  memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
  stamp_value = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    const UF_long entry_end = group_suffix_ptr[group + 1u];
    UF_long entry_cursor = group_suffix_ptr[group];
    stamp_value++;
    if (stamp_value == 0u) {
      memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
      stamp_value = 1u;
    }
    const UF_long stamp = stamp_value;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = selected_runs[pos];
      UF_long suffix_begin = 0u;
      UF_long ulen = 0u;
      UF_long block_start = 0u;
      const UF_long *ui = NULL;
      if (!kls_refactor_algorithm5_payoff_run_suffix_pattern(
            solver, plan_current, plan_dep, run_count, run,
            run_advance_deps, run_prefix_rows, &suffix_begin, &ulen,
            &block_start, &ui)) {
        goto fail;
      }
      const UF_long current = plan_current[run];
      for (UF_long up = suffix_begin; up < ulen; ++up) {
        const UF_long local_dep = ui[up];
        if (local_dep > UF_long_max - block_start) {
          goto fail;
        }
        const UF_long dep = block_start + local_dep;
        if (dep >= solver->n || dep >= current) {
          goto fail;
        }
        UF_long entry = 0u;
        if (stamp_workspace[dep] != stamp) {
          if (entry_cursor >= entry_end || entry_cursor >= unique_prefix) {
            goto fail;
          }
          entry = entry_cursor++;
          stamp_workspace[dep] = stamp;
          entry_workspace[dep] = entry;
          group_suffix_cols[entry] = dep;
        } else {
          entry = entry_workspace[dep];
          if (entry < group_suffix_ptr[group] || entry >= entry_end ||
              group_suffix_cols[entry] != dep) {
            goto fail;
          }
        }
        if (entry >= expected_unique_deps_total ||
            group_suffix_run_ptr[entry + 1u] == UF_long_max) {
          goto fail;
        }
        group_suffix_run_ptr[entry + 1u]++;
      }
    }
    if (entry_cursor != entry_end) {
      goto fail;
    }
  }

  UF_long ref_prefix = 0u;
  for (UF_long entry = 0u; entry < expected_unique_deps_total; ++entry) {
    const UF_long refs = group_suffix_run_ptr[entry + 1u];
    if (refs > UF_long_max - ref_prefix) {
      goto fail;
    }
    group_suffix_run_ptr[entry] = ref_prefix;
    ref_prefix += refs;
    group_suffix_run_ptr[entry + 1u] = ref_prefix;
  }
  if (ref_prefix != expected_run_refs_total) {
    goto fail;
  }

  group_suffix_runs =
    ref_size > 0u
      ? (UF_long *)malloc(ref_size * sizeof(*group_suffix_runs))
      : NULL;
  group_suffix_up =
    ref_size > 0u ? (UF_long *)malloc(ref_size * sizeof(*group_suffix_up))
                  : NULL;
  fill_cursor =
    unique_size > 0u ? (UF_long *)malloc(unique_size * sizeof(*fill_cursor))
                     : NULL;
  if ((ref_size > 0u &&
       (group_suffix_runs == NULL || group_suffix_up == NULL)) ||
      (unique_size > 0u && fill_cursor == NULL)) {
    goto fail;
  }
  if (unique_size > 0u) {
    memcpy(fill_cursor, group_suffix_run_ptr,
           unique_size * sizeof(*fill_cursor));
  }

  memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
  stamp_value = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    const UF_long entry_end = group_suffix_ptr[group + 1u];
    UF_long entry_cursor = group_suffix_ptr[group];
    stamp_value++;
    if (stamp_value == 0u) {
      memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
      stamp_value = 1u;
    }
    const UF_long stamp = stamp_value;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = selected_runs[pos];
      UF_long suffix_begin = 0u;
      UF_long ulen = 0u;
      UF_long block_start = 0u;
      const UF_long *ui = NULL;
      if (!kls_refactor_algorithm5_payoff_run_suffix_pattern(
            solver, plan_current, plan_dep, run_count, run,
            run_advance_deps, run_prefix_rows, &suffix_begin, &ulen,
            &block_start, &ui)) {
        goto fail;
      }
      const UF_long current = plan_current[run];
      for (UF_long up = suffix_begin; up < ulen; ++up) {
        const UF_long local_dep = ui[up];
        if (local_dep > UF_long_max - block_start) {
          goto fail;
        }
        const UF_long dep = block_start + local_dep;
        if (dep >= solver->n || dep >= current) {
          goto fail;
        }
        UF_long entry = 0u;
        if (stamp_workspace[dep] != stamp) {
          if (entry_cursor >= entry_end) {
            goto fail;
          }
          entry = entry_cursor++;
          stamp_workspace[dep] = stamp;
          entry_workspace[dep] = entry;
        } else {
          entry = entry_workspace[dep];
          if (entry < group_suffix_ptr[group] || entry >= entry_end) {
            goto fail;
          }
        }
        if (entry >= expected_unique_deps_total ||
            fill_cursor[entry] >= group_suffix_run_ptr[entry + 1u]) {
          goto fail;
        }
        const UF_long dst = fill_cursor[entry]++;
        group_suffix_runs[dst] = run;
        group_suffix_up[dst] = up;
      }
    }
    if (entry_cursor != entry_end) {
      goto fail;
    }
  }
  for (UF_long entry = 0u; entry < expected_unique_deps_total; ++entry) {
    if (fill_cursor[entry] != group_suffix_run_ptr[entry + 1u]) {
      goto fail;
    }
  }

  free(stamp_workspace);
  free(entry_workspace);
  free(fill_cursor);
  *group_suffix_ptr_out = group_suffix_ptr;
  *group_suffix_cols_out = group_suffix_cols;
  *group_suffix_run_ptr_out = group_suffix_run_ptr;
  *group_suffix_runs_out = group_suffix_runs;
  *group_suffix_up_out = group_suffix_up;
  return 1;

fail:
  free(group_suffix_ptr);
  free(group_suffix_cols);
  free(group_suffix_run_ptr);
  free(group_suffix_runs);
  free(group_suffix_up);
  free(fill_cursor);
  free(stamp_workspace);
  free(entry_workspace);
  return 0;
}

static int kls_refactor_algorithm5_payoff_run_advance_pattern(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  UF_long run,
  const UF_long *run_advance_deps,
  UF_long *advance_deps_out,
  UF_long *block_start_out,
  const UF_long **ui_out) {
  if (advance_deps_out != NULL) {
    *advance_deps_out = 0u;
  }
  if (block_start_out != NULL) {
    *block_start_out = 0u;
  }
  if (ui_out != NULL) {
    *ui_out = NULL;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Ulen == NULL || plan_current == NULL ||
      plan_dep == NULL || run_advance_deps == NULL ||
      advance_deps_out == NULL || block_start_out == NULL ||
      ui_out == NULL) {
    return 0;
  }

  UF_long dep_pos = 0u;
  UF_long block_start = 0u;
  const UF_long *ui = NULL;
  if (!kls_supernode_consumer_plan_run_dep_position(
        solver, plan_current, plan_dep, run_count, run, &dep_pos,
        &block_start, &ui)) {
    return 0;
  }
  if (run >= run_count || run_advance_deps[run] != dep_pos) {
    return 0;
  }
  const UF_long current = plan_current[run];
  if (current >= solver->n || dep_pos > solver->numeric->Ulen[current] ||
      (dep_pos > 0u && ui == NULL)) {
    return 0;
  }

  *advance_deps_out = dep_pos;
  *block_start_out = block_start;
  *ui_out = ui;
  return 1;
}

static int kls_count_refactor_algorithm5_payoff_group_advance_sharing(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  const UF_long *selected_runs,
  const UF_long *group_ptr,
  UF_long group_count,
  const UF_long *run_advance_deps,
  UF_long *unique_deps_total_out,
  UF_long *duplicate_deps_total_out,
  UF_long *shared_deps_total_out,
  UF_long *max_dep_fanout_out,
  UF_long *duplicate_update_entries_total_out) {
  if (unique_deps_total_out != NULL) {
    *unique_deps_total_out = 0u;
  }
  if (duplicate_deps_total_out != NULL) {
    *duplicate_deps_total_out = 0u;
  }
  if (shared_deps_total_out != NULL) {
    *shared_deps_total_out = 0u;
  }
  if (max_dep_fanout_out != NULL) {
    *max_dep_fanout_out = 0u;
  }
  if (duplicate_update_entries_total_out != NULL) {
    *duplicate_update_entries_total_out = 0u;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Llen == NULL || solver->numeric->Ulen == NULL ||
      plan_current == NULL || plan_dep == NULL ||
      unique_deps_total_out == NULL || duplicate_deps_total_out == NULL ||
      shared_deps_total_out == NULL || max_dep_fanout_out == NULL ||
      duplicate_update_entries_total_out == NULL) {
    return 0;
  }
  if (group_count == 0u) {
    return 1;
  }
  if (selected_runs == NULL || group_ptr == NULL ||
      run_advance_deps == NULL) {
    return 0;
  }
  const size_t n = (size_t)solver->n;
  if ((UF_long)n != solver->n || n > SIZE_MAX / sizeof(UF_long)) {
    return 0;
  }
  const size_t n_alloc = n > 0u ? n : 1u;
  UF_long *stamp_workspace =
    (UF_long *)calloc(n_alloc, sizeof(*stamp_workspace));
  UF_long *fanout_workspace =
    (UF_long *)calloc(n_alloc, sizeof(*fanout_workspace));
  if (stamp_workspace == NULL || fanout_workspace == NULL) {
    free(stamp_workspace);
    free(fanout_workspace);
    return 0;
  }

  const UF_long selected_run_count = group_ptr[group_count];
  UF_long stamp_value = 0u;
  UF_long unique_total = 0u;
  UF_long duplicate_total = 0u;
  UF_long shared_total = 0u;
  UF_long max_fanout = 0u;
  UF_long duplicate_update_total = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    if (begin > end || end > selected_run_count) {
      free(stamp_workspace);
      free(fanout_workspace);
      return 0;
    }
    stamp_value++;
    if (stamp_value == 0u) {
      memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
      stamp_value = 1u;
    }
    const UF_long stamp = stamp_value;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = selected_runs[pos];
      if (run >= run_count) {
        free(stamp_workspace);
        free(fanout_workspace);
        return 0;
      }
      UF_long advance_deps = 0u;
      UF_long block_start = 0u;
      const UF_long *ui = NULL;
      if (!kls_refactor_algorithm5_payoff_run_advance_pattern(
            solver, plan_current, plan_dep, run_count, run, run_advance_deps,
            &advance_deps, &block_start, &ui)) {
        free(stamp_workspace);
        free(fanout_workspace);
        return 0;
      }
      const UF_long current = plan_current[run];
      for (UF_long up = 0u; up < advance_deps; ++up) {
        const UF_long local_dep = ui[up];
        if (local_dep > UF_long_max - block_start) {
          free(stamp_workspace);
          free(fanout_workspace);
          return 0;
        }
        const UF_long dep = block_start + local_dep;
        if (dep >= solver->n || dep >= current ||
            solver->numeric->Llen[dep] == UF_long_max) {
          free(stamp_workspace);
          free(fanout_workspace);
          return 0;
        }
        const UF_long update_entries = 1u + solver->numeric->Llen[dep];
        if (stamp_workspace[dep] != stamp) {
          if (unique_total == UF_long_max) {
            free(stamp_workspace);
            free(fanout_workspace);
            return 0;
          }
          stamp_workspace[dep] = stamp;
          fanout_workspace[dep] = 1u;
          unique_total++;
          if (max_fanout == 0u) {
            max_fanout = 1u;
          }
          continue;
        }
        if (fanout_workspace[dep] == UF_long_max ||
            duplicate_total == UF_long_max ||
            duplicate_update_total > UF_long_max - update_entries) {
          free(stamp_workspace);
          free(fanout_workspace);
          return 0;
        }
        fanout_workspace[dep]++;
        duplicate_total++;
        duplicate_update_total += update_entries;
        if (fanout_workspace[dep] == 2u) {
          if (shared_total == UF_long_max) {
            free(stamp_workspace);
            free(fanout_workspace);
            return 0;
          }
          shared_total++;
        }
        if (fanout_workspace[dep] > max_fanout) {
          max_fanout = fanout_workspace[dep];
        }
      }
    }
  }

  free(stamp_workspace);
  free(fanout_workspace);
  *unique_deps_total_out = unique_total;
  *duplicate_deps_total_out = duplicate_total;
  *shared_deps_total_out = shared_total;
  *max_dep_fanout_out = max_fanout;
  *duplicate_update_entries_total_out = duplicate_update_total;
  return 1;
}

static int kls_build_refactor_algorithm5_payoff_group_advance_map(
  const kls_solver *solver,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long run_count,
  const UF_long *selected_runs,
  const UF_long *group_ptr,
  UF_long group_count,
  const UF_long *run_advance_deps,
  UF_long expected_unique_deps_total,
  UF_long expected_run_refs_total,
  UF_long **group_advance_map_ptr_out,
  UF_long **group_advance_map_cols_out,
  UF_long **group_advance_map_run_ptr_out,
  UF_long **group_advance_map_runs_out,
  UF_long **group_advance_map_up_out) {
  if (group_advance_map_ptr_out != NULL) {
    *group_advance_map_ptr_out = NULL;
  }
  if (group_advance_map_cols_out != NULL) {
    *group_advance_map_cols_out = NULL;
  }
  if (group_advance_map_run_ptr_out != NULL) {
    *group_advance_map_run_ptr_out = NULL;
  }
  if (group_advance_map_runs_out != NULL) {
    *group_advance_map_runs_out = NULL;
  }
  if (group_advance_map_up_out != NULL) {
    *group_advance_map_up_out = NULL;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Ulen == NULL || plan_current == NULL ||
      plan_dep == NULL || group_advance_map_ptr_out == NULL ||
      group_advance_map_cols_out == NULL ||
      group_advance_map_run_ptr_out == NULL ||
      group_advance_map_runs_out == NULL ||
      group_advance_map_up_out == NULL) {
    return 0;
  }
  if (group_count == 0u) {
    return expected_unique_deps_total == 0u && expected_run_refs_total == 0u;
  }
  if (selected_runs == NULL || group_ptr == NULL ||
      run_advance_deps == NULL) {
    return 0;
  }

  const size_t group_count_size = (size_t)group_count;
  const size_t unique_size = (size_t)expected_unique_deps_total;
  const size_t ref_size = (size_t)expected_run_refs_total;
  const size_t n = (size_t)solver->n;
  if ((UF_long)group_count_size != group_count ||
      (UF_long)unique_size != expected_unique_deps_total ||
      (UF_long)ref_size != expected_run_refs_total ||
      (UF_long)n != solver->n ||
      group_count_size > (SIZE_MAX / sizeof(UF_long)) - 1u ||
      unique_size > (SIZE_MAX / sizeof(UF_long)) - 1u ||
      ref_size > SIZE_MAX / sizeof(UF_long) ||
      n > SIZE_MAX / sizeof(UF_long)) {
    return 0;
  }
  const size_t n_alloc = n > 0u ? n : 1u;

  UF_long *group_advance_map_ptr =
    (UF_long *)calloc(group_count_size + 1u, sizeof(*group_advance_map_ptr));
  UF_long *stamp_workspace =
    (UF_long *)calloc(n_alloc, sizeof(*stamp_workspace));
  UF_long *entry_workspace =
    (UF_long *)malloc(n_alloc * sizeof(*entry_workspace));
  UF_long *group_advance_map_cols = NULL;
  UF_long *group_advance_map_run_ptr = NULL;
  UF_long *group_advance_map_runs = NULL;
  UF_long *group_advance_map_up = NULL;
  UF_long *fill_cursor = NULL;
  if (group_advance_map_ptr == NULL || stamp_workspace == NULL ||
      entry_workspace == NULL) {
    goto fail;
  }

  const UF_long selected_run_count = group_ptr[group_count];
  UF_long stamp_value = 0u;
  UF_long counted_unique = 0u;
  UF_long counted_refs = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    if (begin > end || end > selected_run_count) {
      goto fail;
    }
    stamp_value++;
    if (stamp_value == 0u) {
      memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
      stamp_value = 1u;
    }
    const UF_long stamp = stamp_value;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = selected_runs[pos];
      if (run >= run_count) {
        goto fail;
      }
      UF_long advance_deps = 0u;
      UF_long block_start = 0u;
      const UF_long *ui = NULL;
      if (!kls_refactor_algorithm5_payoff_run_advance_pattern(
            solver, plan_current, plan_dep, run_count, run, run_advance_deps,
            &advance_deps, &block_start, &ui)) {
        goto fail;
      }
      const UF_long current = plan_current[run];
      for (UF_long up = 0u; up < advance_deps; ++up) {
        const UF_long local_dep = ui[up];
        if (local_dep > UF_long_max - block_start ||
            counted_refs == UF_long_max) {
          goto fail;
        }
        const UF_long dep = block_start + local_dep;
        if (dep >= solver->n || dep >= current) {
          goto fail;
        }
        counted_refs++;
        if (stamp_workspace[dep] != stamp) {
          if (counted_unique == UF_long_max ||
              group_advance_map_ptr[group + 1u] == UF_long_max) {
            goto fail;
          }
          stamp_workspace[dep] = stamp;
          counted_unique++;
          group_advance_map_ptr[group + 1u]++;
        }
      }
    }
  }
  if (counted_unique != expected_unique_deps_total ||
      counted_refs != expected_run_refs_total) {
    goto fail;
  }

  UF_long unique_prefix = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long group_unique = group_advance_map_ptr[group + 1u];
    if (group_unique > UF_long_max - unique_prefix) {
      goto fail;
    }
    group_advance_map_ptr[group] = unique_prefix;
    unique_prefix += group_unique;
    group_advance_map_ptr[group + 1u] = unique_prefix;
  }
  if (unique_prefix != expected_unique_deps_total) {
    goto fail;
  }

  const size_t run_ptr_size = unique_size + 1u;
  group_advance_map_cols =
    unique_size > 0u
      ? (UF_long *)malloc(unique_size * sizeof(*group_advance_map_cols))
      : NULL;
  group_advance_map_run_ptr =
    (UF_long *)calloc(run_ptr_size, sizeof(*group_advance_map_run_ptr));
  if ((unique_size > 0u && group_advance_map_cols == NULL) ||
      group_advance_map_run_ptr == NULL) {
    goto fail;
  }

  memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
  stamp_value = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    const UF_long entry_end = group_advance_map_ptr[group + 1u];
    UF_long entry_cursor = group_advance_map_ptr[group];
    stamp_value++;
    if (stamp_value == 0u) {
      memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
      stamp_value = 1u;
    }
    const UF_long stamp = stamp_value;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = selected_runs[pos];
      UF_long advance_deps = 0u;
      UF_long block_start = 0u;
      const UF_long *ui = NULL;
      if (!kls_refactor_algorithm5_payoff_run_advance_pattern(
            solver, plan_current, plan_dep, run_count, run, run_advance_deps,
            &advance_deps, &block_start, &ui)) {
        goto fail;
      }
      const UF_long current = plan_current[run];
      for (UF_long up = 0u; up < advance_deps; ++up) {
        const UF_long local_dep = ui[up];
        if (local_dep > UF_long_max - block_start) {
          goto fail;
        }
        const UF_long dep = block_start + local_dep;
        if (dep >= solver->n || dep >= current) {
          goto fail;
        }
        UF_long entry = 0u;
        if (stamp_workspace[dep] != stamp) {
          if (entry_cursor >= entry_end || entry_cursor >= unique_prefix) {
            goto fail;
          }
          entry = entry_cursor++;
          stamp_workspace[dep] = stamp;
          entry_workspace[dep] = entry;
          group_advance_map_cols[entry] = dep;
        } else {
          entry = entry_workspace[dep];
          if (entry < group_advance_map_ptr[group] || entry >= entry_end ||
              group_advance_map_cols[entry] != dep) {
            goto fail;
          }
        }
        if (entry >= expected_unique_deps_total ||
            group_advance_map_run_ptr[entry + 1u] == UF_long_max) {
          goto fail;
        }
        group_advance_map_run_ptr[entry + 1u]++;
      }
    }
    if (entry_cursor != entry_end) {
      goto fail;
    }
  }

  UF_long ref_prefix = 0u;
  for (UF_long entry = 0u; entry < expected_unique_deps_total; ++entry) {
    const UF_long refs = group_advance_map_run_ptr[entry + 1u];
    if (refs > UF_long_max - ref_prefix) {
      goto fail;
    }
    group_advance_map_run_ptr[entry] = ref_prefix;
    ref_prefix += refs;
    group_advance_map_run_ptr[entry + 1u] = ref_prefix;
  }
  if (ref_prefix != expected_run_refs_total) {
    goto fail;
  }

  group_advance_map_runs =
    ref_size > 0u
      ? (UF_long *)malloc(ref_size * sizeof(*group_advance_map_runs))
      : NULL;
  group_advance_map_up =
    ref_size > 0u
      ? (UF_long *)malloc(ref_size * sizeof(*group_advance_map_up))
      : NULL;
  fill_cursor =
    unique_size > 0u ? (UF_long *)malloc(unique_size * sizeof(*fill_cursor))
                     : NULL;
  if ((ref_size > 0u &&
       (group_advance_map_runs == NULL || group_advance_map_up == NULL)) ||
      (unique_size > 0u && fill_cursor == NULL)) {
    goto fail;
  }
  if (unique_size > 0u) {
    memcpy(fill_cursor, group_advance_map_run_ptr,
           unique_size * sizeof(*fill_cursor));
  }

  memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
  stamp_value = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    const UF_long entry_end = group_advance_map_ptr[group + 1u];
    UF_long entry_cursor = group_advance_map_ptr[group];
    stamp_value++;
    if (stamp_value == 0u) {
      memset(stamp_workspace, 0, n_alloc * sizeof(*stamp_workspace));
      stamp_value = 1u;
    }
    const UF_long stamp = stamp_value;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = selected_runs[pos];
      UF_long advance_deps = 0u;
      UF_long block_start = 0u;
      const UF_long *ui = NULL;
      if (!kls_refactor_algorithm5_payoff_run_advance_pattern(
            solver, plan_current, plan_dep, run_count, run, run_advance_deps,
            &advance_deps, &block_start, &ui)) {
        goto fail;
      }
      const UF_long current = plan_current[run];
      for (UF_long up = 0u; up < advance_deps; ++up) {
        const UF_long local_dep = ui[up];
        if (local_dep > UF_long_max - block_start) {
          goto fail;
        }
        const UF_long dep = block_start + local_dep;
        if (dep >= solver->n || dep >= current) {
          goto fail;
        }
        UF_long entry = 0u;
        if (stamp_workspace[dep] != stamp) {
          if (entry_cursor >= entry_end) {
            goto fail;
          }
          entry = entry_cursor++;
          stamp_workspace[dep] = stamp;
          entry_workspace[dep] = entry;
        } else {
          entry = entry_workspace[dep];
          if (entry < group_advance_map_ptr[group] || entry >= entry_end) {
            goto fail;
          }
        }
        if (entry >= expected_unique_deps_total ||
            fill_cursor[entry] >= group_advance_map_run_ptr[entry + 1u]) {
          goto fail;
        }
        const UF_long dst = fill_cursor[entry]++;
        group_advance_map_runs[dst] = run;
        group_advance_map_up[dst] = up;
      }
    }
    if (entry_cursor != entry_end) {
      goto fail;
    }
  }
  for (UF_long entry = 0u; entry < expected_unique_deps_total; ++entry) {
    if (fill_cursor[entry] != group_advance_map_run_ptr[entry + 1u]) {
      goto fail;
    }
  }

  free(stamp_workspace);
  free(entry_workspace);
  free(fill_cursor);
  *group_advance_map_ptr_out = group_advance_map_ptr;
  *group_advance_map_cols_out = group_advance_map_cols;
  *group_advance_map_run_ptr_out = group_advance_map_run_ptr;
  *group_advance_map_runs_out = group_advance_map_runs;
  *group_advance_map_up_out = group_advance_map_up;
  return 1;

fail:
  free(group_advance_map_ptr);
  free(group_advance_map_cols);
  free(group_advance_map_run_ptr);
  free(group_advance_map_runs);
  free(group_advance_map_up);
  free(fill_cursor);
  free(stamp_workspace);
  free(entry_workspace);
  return 0;
}

static int kls_count_supernode_consumer_plan_first_dep_shape_batches(
  const kls_solver *solver,
  const UF_long *group_ptr,
  const UF_long *group_runs,
  const UF_long *group_rows,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long group_count,
  UF_long group_run_count,
  UF_long run_count,
  UF_long *shape_batch_count_out,
  UF_long *shape_batch_run_count_out,
  UF_long *shape_batch_run_rows_out,
  UF_long *shape_batch_small_run_count_out,
  UF_long *shape_batch_small_run_rows_out,
  UF_long *shape_batch_max_runs_out) {
  if (shape_batch_count_out != NULL) {
    *shape_batch_count_out = 0u;
  }
  if (shape_batch_run_count_out != NULL) {
    *shape_batch_run_count_out = 0u;
  }
  if (shape_batch_run_rows_out != NULL) {
    *shape_batch_run_rows_out = 0u;
  }
  if (shape_batch_small_run_count_out != NULL) {
    *shape_batch_small_run_count_out = 0u;
  }
  if (shape_batch_small_run_rows_out != NULL) {
    *shape_batch_small_run_rows_out = 0u;
  }
  if (shape_batch_max_runs_out != NULL) {
    *shape_batch_max_runs_out = 0u;
  }
  if (solver == NULL || group_ptr == NULL || group_runs == NULL ||
      group_rows == NULL || plan_current == NULL || plan_dep == NULL ||
      shape_batch_count_out == NULL ||
      shape_batch_run_count_out == NULL ||
      shape_batch_run_rows_out == NULL ||
      shape_batch_small_run_count_out == NULL ||
      shape_batch_small_run_rows_out == NULL ||
      shape_batch_max_runs_out == NULL) {
    return 0;
  }
  if (group_count == 0u || group_run_count == 0u || run_count == 0u) {
    return 1;
  }

  UF_long shape_batch_count = 0u;
  UF_long shape_batch_run_count = 0u;
  UF_long shape_batch_run_rows = 0u;
  UF_long shape_batch_small_run_count = 0u;
  UF_long shape_batch_small_run_rows = 0u;
  UF_long shape_batch_max_runs = 0u;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    if (begin > end || end > group_run_count) {
      return 0;
    }
    const UF_long rows = group_rows[group];
    UF_long first_dep_runs = 0u;
    UF_long first_dep_rows = 0u;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = group_runs[pos];
      if (run >= run_count) {
        return 0;
      }
      if (!kls_supernode_consumer_plan_run_is_first_dependency(
            solver, plan_current, plan_dep, run_count, run)) {
        continue;
      }
      if (first_dep_runs == UF_long_max ||
          rows > UF_long_max - first_dep_rows) {
        return 0;
      }
      first_dep_runs++;
      first_dep_rows += rows;
    }
    if (first_dep_runs < 2u) {
      continue;
    }
    if (shape_batch_count == UF_long_max ||
        first_dep_runs > UF_long_max - shape_batch_run_count ||
        first_dep_rows > UF_long_max - shape_batch_run_rows) {
      return 0;
    }
    shape_batch_count++;
    shape_batch_run_count += first_dep_runs;
    shape_batch_run_rows += first_dep_rows;
    if (rows < KLS_EGRAPH_RAGGED_U_SUPERNODE_MIN_ROWS) {
      if (first_dep_runs > UF_long_max - shape_batch_small_run_count ||
          first_dep_rows > UF_long_max - shape_batch_small_run_rows) {
        return 0;
      }
      shape_batch_small_run_count += first_dep_runs;
      shape_batch_small_run_rows += first_dep_rows;
    }
    if (first_dep_runs > shape_batch_max_runs) {
      shape_batch_max_runs = first_dep_runs;
    }
  }

  *shape_batch_count_out = shape_batch_count;
  *shape_batch_run_count_out = shape_batch_run_count;
  *shape_batch_run_rows_out = shape_batch_run_rows;
  *shape_batch_small_run_count_out = shape_batch_small_run_count;
  *shape_batch_small_run_rows_out = shape_batch_small_run_rows;
  *shape_batch_max_runs_out = shape_batch_max_runs;
  return 1;
}

static int kls_count_supernode_consumer_plan_shape_batch_advance_costs(
  const kls_solver *solver,
  const UF_long *group_ptr,
  const UF_long *group_runs,
  const UF_long *group_rows,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long group_count,
  UF_long group_run_count,
  UF_long run_count,
  UF_long *advance_count_out,
  UF_long *advance_run_count_out,
  UF_long *advance_run_rows_out,
  UF_long *advance_dep_count_out,
  double *advance_work_out,
  UF_long *advance_max_deps_out,
  double *advance_max_work_out) {
  if (advance_count_out != NULL) {
    *advance_count_out = 0u;
  }
  if (advance_run_count_out != NULL) {
    *advance_run_count_out = 0u;
  }
  if (advance_run_rows_out != NULL) {
    *advance_run_rows_out = 0u;
  }
  if (advance_dep_count_out != NULL) {
    *advance_dep_count_out = 0u;
  }
  if (advance_work_out != NULL) {
    *advance_work_out = 0.0;
  }
  if (advance_max_deps_out != NULL) {
    *advance_max_deps_out = 0u;
  }
  if (advance_max_work_out != NULL) {
    *advance_max_work_out = 0.0;
  }
  if (solver == NULL || group_ptr == NULL || group_runs == NULL ||
      group_rows == NULL || plan_current == NULL || plan_dep == NULL ||
      advance_count_out == NULL ||
      advance_run_count_out == NULL ||
      advance_run_rows_out == NULL ||
      advance_dep_count_out == NULL ||
      advance_work_out == NULL ||
      advance_max_deps_out == NULL ||
      advance_max_work_out == NULL) {
    return 0;
  }
  if (group_count == 0u || group_run_count == 0u || run_count == 0u) {
    return 1;
  }

  UF_long advance_count = 0u;
  UF_long advance_run_count = 0u;
  UF_long advance_run_rows = 0u;
  UF_long advance_dep_count = 0u;
  double advance_work = 0.0;
  UF_long advance_max_deps = 0u;
  double advance_max_work = 0.0;
  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    if (begin > end || end > group_run_count) {
      return 0;
    }
    const UF_long rows = group_rows[group];
    UF_long group_runs_found = 0u;
    UF_long group_run_rows = 0u;
    UF_long group_dep_count = 0u;
    double group_work = 0.0;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = group_runs[pos];
      if (run >= run_count) {
        return 0;
      }
      UF_long run_deps = 0u;
      double run_work = 0.0;
      if (!kls_supernode_consumer_plan_run_advance_cost(
            solver, plan_current, plan_dep, run_count, run,
            &run_deps, &run_work)) {
        continue;
      }
      if (group_runs_found == UF_long_max ||
          rows > UF_long_max - group_run_rows ||
          run_deps > UF_long_max - group_dep_count) {
        return 0;
      }
      group_runs_found++;
      group_run_rows += rows;
      group_dep_count += run_deps;
      group_work += run_work;
      if (run_deps > advance_max_deps) {
        advance_max_deps = run_deps;
      }
      if (run_work > advance_max_work) {
        advance_max_work = run_work;
      }
    }
    if (group_runs_found < 2u) {
      continue;
    }
    if (advance_count == UF_long_max ||
        group_runs_found > UF_long_max - advance_run_count ||
        group_run_rows > UF_long_max - advance_run_rows ||
        group_dep_count > UF_long_max - advance_dep_count) {
      return 0;
    }
    advance_count++;
    advance_run_count += group_runs_found;
    advance_run_rows += group_run_rows;
    advance_dep_count += group_dep_count;
    advance_work += group_work;
  }

  *advance_count_out = advance_count;
  *advance_run_count_out = advance_run_count;
  *advance_run_rows_out = advance_run_rows;
  *advance_dep_count_out = advance_dep_count;
  *advance_work_out = advance_work;
  *advance_max_deps_out = advance_max_deps;
  *advance_max_work_out = advance_max_work;
  return 1;
}

static int kls_supernode_consumer_plan_shape_group_update_entries(
  const kls_solver *solver,
  UF_long panel_start,
  UF_long panel_offset,
  UF_long width,
  UF_long *per_run_entries_out) {
  if (per_run_entries_out != NULL) {
    *per_run_entries_out = 0u;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Llen == NULL || per_run_entries_out == NULL ||
      width <= 1u || width > UF_long_max / width ||
      panel_start > solver->n || panel_offset > solver->n - panel_start) {
    return 0;
  }
  const UF_long start = panel_start + panel_offset;
  if (start > solver->n || width > solver->n - start) {
    return 0;
  }

  const UF_long trsv_entries = (width * (width - 1u)) / 2u;
  UF_long trailing_entries = 0u;
  UF_long k1 = 0u;
  UF_long block_size = 0u;
  UF_long local_start = 0u;
  const int exact_rows =
    solver->refactor_l_indices != NULL &&
    kls_refactor_supernode_panel_block_info(
      solver, start, start + width, &k1, &block_size, &local_start);
  (void)k1;
  if (exact_rows) {
    if (local_start > block_size || width > block_size - local_start) {
      return 0;
    }
    const UF_long skip_begin = local_start;
    const UF_long skip_end = local_start + width;
    for (UF_long local = 0u; local < width; ++local) {
      const UF_long col = start + local;
      const UF_long *rows = solver->refactor_l_indices[col];
      const UF_long length = solver->numeric->Llen[col];
      if (rows == NULL && length > 0u) {
        return 0;
      }
      for (UF_long p = 0u; p < length; ++p) {
        const UF_long row = rows[p];
        if (row >= block_size) {
          return 0;
        }
        if (row >= skip_begin && row < skip_end) {
          continue;
        }
        if (trailing_entries == UF_long_max) {
          return 0;
        }
        trailing_entries++;
      }
    }
  } else {
    for (UF_long local = 0u; local < width; ++local) {
      const UF_long col = start + local;
      const UF_long length = solver->numeric->Llen[col];
      const UF_long internal = width - local - 1u;
      const UF_long trailing = length > internal ? length - internal : 0u;
      if (trailing > UF_long_max - trailing_entries) {
        return 0;
      }
      trailing_entries += trailing;
    }
  }

  if (trailing_entries > UF_long_max - trsv_entries) {
    return 0;
  }
  *per_run_entries_out = trsv_entries + trailing_entries;
  return 1;
}

static int kls_count_supernode_consumer_plan_shape_bounded_advance_batches(
  const kls_solver *solver,
  const UF_long *group_ptr,
  const UF_long *group_runs,
  const UF_long *group_panel_start,
  const UF_long *group_panel_offset,
  const UF_long *group_rows,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long group_count,
  UF_long group_run_count,
  UF_long run_count,
  UF_long dep_limit,
  UF_long *bounded_count_out,
  UF_long *bounded_run_count_out,
  UF_long *bounded_run_rows_out,
  UF_long *bounded_dep_count_out,
  UF_long *bounded_update_entries_out,
  double *bounded_work_out,
  UF_long *bounded_max_run_deps_out,
  double *bounded_max_run_work_out,
  UF_long *payoff_count_out,
  UF_long *payoff_run_count_out,
  UF_long *payoff_run_rows_out,
  UF_long *payoff_update_entries_out,
  double *payoff_advance_work_out,
  double *max_payoff_ratio_out) {
  if (bounded_count_out != NULL) {
    *bounded_count_out = 0u;
  }
  if (bounded_run_count_out != NULL) {
    *bounded_run_count_out = 0u;
  }
  if (bounded_run_rows_out != NULL) {
    *bounded_run_rows_out = 0u;
  }
  if (bounded_dep_count_out != NULL) {
    *bounded_dep_count_out = 0u;
  }
  if (bounded_update_entries_out != NULL) {
    *bounded_update_entries_out = 0u;
  }
  if (bounded_work_out != NULL) {
    *bounded_work_out = 0.0;
  }
  if (bounded_max_run_deps_out != NULL) {
    *bounded_max_run_deps_out = 0u;
  }
  if (bounded_max_run_work_out != NULL) {
    *bounded_max_run_work_out = 0.0;
  }
  if (payoff_count_out != NULL) {
    *payoff_count_out = 0u;
  }
  if (payoff_run_count_out != NULL) {
    *payoff_run_count_out = 0u;
  }
  if (payoff_run_rows_out != NULL) {
    *payoff_run_rows_out = 0u;
  }
  if (payoff_update_entries_out != NULL) {
    *payoff_update_entries_out = 0u;
  }
  if (payoff_advance_work_out != NULL) {
    *payoff_advance_work_out = 0.0;
  }
  if (max_payoff_ratio_out != NULL) {
    *max_payoff_ratio_out = 0.0;
  }
  if (solver == NULL || group_ptr == NULL || group_runs == NULL ||
      group_panel_start == NULL || group_panel_offset == NULL ||
      group_rows == NULL || plan_current == NULL || plan_dep == NULL ||
      bounded_count_out == NULL ||
      bounded_run_count_out == NULL ||
      bounded_run_rows_out == NULL ||
      bounded_dep_count_out == NULL ||
      bounded_update_entries_out == NULL ||
      bounded_work_out == NULL ||
      bounded_max_run_deps_out == NULL ||
      bounded_max_run_work_out == NULL ||
      payoff_count_out == NULL ||
      payoff_run_count_out == NULL ||
      payoff_run_rows_out == NULL ||
      payoff_update_entries_out == NULL ||
      payoff_advance_work_out == NULL ||
      max_payoff_ratio_out == NULL) {
    return 0;
  }
  if (group_count == 0u || group_run_count == 0u || run_count == 0u) {
    return 1;
  }

  UF_long bounded_count = 0u;
  UF_long bounded_run_count = 0u;
  UF_long bounded_run_rows = 0u;
  UF_long bounded_dep_count = 0u;
  UF_long bounded_update_entries = 0u;
  double bounded_work = 0.0;
  UF_long bounded_max_run_deps = 0u;
  double bounded_max_run_work = 0.0;
  UF_long payoff_count = 0u;
  UF_long payoff_run_count = 0u;
  UF_long payoff_run_rows = 0u;
  UF_long payoff_update_entries = 0u;
  double payoff_advance_work = 0.0;
  double max_payoff_ratio = 0.0;

  for (UF_long group = 0u; group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    if (begin > end || end > group_run_count) {
      return 0;
    }
    const UF_long runs = end - begin;
    if (runs < 2u) {
      continue;
    }
    const UF_long rows = group_rows[group];
    if (rows == 0u || rows > UF_long_max / runs) {
      return 0;
    }
    const UF_long group_run_rows = rows * runs;

    UF_long per_run_update_entries = 0u;
    if (!kls_supernode_consumer_plan_shape_group_update_entries(
          solver, group_panel_start[group], group_panel_offset[group],
          rows, &per_run_update_entries)) {
      continue;
    }
    if (per_run_update_entries > 0u &&
        runs > UF_long_max / per_run_update_entries) {
      return 0;
    }
    const UF_long group_update_entries = per_run_update_entries * runs;

    UF_long group_dep_count = 0u;
    double group_work = 0.0;
    UF_long group_max_run_deps = 0u;
    double group_max_run_work = 0.0;
    int bounded = 1;
    for (UF_long pos = begin; pos < end; ++pos) {
      const UF_long run = group_runs[pos];
      if (run >= run_count) {
        return 0;
      }
      UF_long run_deps = 0u;
      double run_work = 0.0;
      if (!kls_supernode_consumer_plan_run_advance_cost(
            solver, plan_current, plan_dep, run_count, run,
            &run_deps, &run_work)) {
        bounded = 0;
        break;
      }
      if (run_deps > dep_limit) {
        bounded = 0;
        break;
      }
      if (run_deps > UF_long_max - group_dep_count) {
        return 0;
      }
      group_dep_count += run_deps;
      group_work += run_work;
      if (run_deps > group_max_run_deps) {
        group_max_run_deps = run_deps;
      }
      if (run_work > group_max_run_work) {
        group_max_run_work = run_work;
      }
    }
    if (!bounded) {
      continue;
    }
    if (bounded_count == UF_long_max ||
        runs > UF_long_max - bounded_run_count ||
        group_run_rows > UF_long_max - bounded_run_rows ||
        group_dep_count > UF_long_max - bounded_dep_count ||
        group_update_entries > UF_long_max - bounded_update_entries) {
      return 0;
    }
    bounded_count++;
    bounded_run_count += runs;
    bounded_run_rows += group_run_rows;
    bounded_dep_count += group_dep_count;
    bounded_update_entries += group_update_entries;
    bounded_work += group_work;
    if (group_max_run_deps > bounded_max_run_deps) {
      bounded_max_run_deps = group_max_run_deps;
    }
    if (group_max_run_work > bounded_max_run_work) {
      bounded_max_run_work = group_max_run_work;
    }

    const double update_work = (double)group_update_entries;
    double payoff_ratio = 0.0;
    if (group_work > 0.0) {
      payoff_ratio = update_work / group_work;
    } else if (group_update_entries > 0u) {
      payoff_ratio = DBL_MAX;
    }
    if (payoff_ratio > max_payoff_ratio) {
      max_payoff_ratio = payoff_ratio;
    }
    if (update_work >= group_work) {
      if (payoff_count == UF_long_max ||
          runs > UF_long_max - payoff_run_count ||
          group_run_rows > UF_long_max - payoff_run_rows ||
          group_update_entries > UF_long_max - payoff_update_entries) {
        return 0;
      }
      payoff_count++;
      payoff_run_count += runs;
      payoff_run_rows += group_run_rows;
      payoff_update_entries += group_update_entries;
      payoff_advance_work += group_work;
    }
  }

  *bounded_count_out = bounded_count;
  *bounded_run_count_out = bounded_run_count;
  *bounded_run_rows_out = bounded_run_rows;
  *bounded_dep_count_out = bounded_dep_count;
  *bounded_update_entries_out = bounded_update_entries;
  *bounded_work_out = bounded_work;
  *bounded_max_run_deps_out = bounded_max_run_deps;
  *bounded_max_run_work_out = bounded_max_run_work;
  *payoff_count_out = payoff_count;
  *payoff_run_count_out = payoff_run_count;
  *payoff_run_rows_out = payoff_run_rows;
  *payoff_update_entries_out = payoff_update_entries;
  *payoff_advance_work_out = payoff_advance_work;
  *max_payoff_ratio_out = max_payoff_ratio;
  return 1;
}

static int kls_same_supernode_consumer_plan_prefix(
  UF_long block_start_a,
  const UF_long *ui_a,
  UF_long len_a,
  UF_long block_start_b,
  const UF_long *ui_b,
  UF_long len_b) {
  if (block_start_a != block_start_b || len_a != len_b) {
    return 0;
  }
  for (UF_long pos = 0u; pos < len_a; ++pos) {
    if (ui_a == NULL || ui_b == NULL || ui_a[pos] != ui_b[pos]) {
      return 0;
    }
  }
  return 1;
}

static int kls_count_supernode_consumer_plan_prefix_advance_batches(
  const kls_solver *solver,
  const UF_long *group_ptr,
  const UF_long *group_runs,
  const UF_long *group_rows,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  UF_long group_count,
  UF_long group_run_count,
  UF_long run_count,
  UF_long max_group_runs,
  UF_long *batch_count_out,
  UF_long *batch_run_count_out,
  UF_long *batch_run_rows_out,
  UF_long *batch_dep_count_out,
  double *batch_work_out,
  UF_long *batch_max_runs_out,
  UF_long *batch_max_deps_out,
  double *batch_max_work_out) {
  if (batch_count_out != NULL) {
    *batch_count_out = 0u;
  }
  if (batch_run_count_out != NULL) {
    *batch_run_count_out = 0u;
  }
  if (batch_run_rows_out != NULL) {
    *batch_run_rows_out = 0u;
  }
  if (batch_dep_count_out != NULL) {
    *batch_dep_count_out = 0u;
  }
  if (batch_work_out != NULL) {
    *batch_work_out = 0.0;
  }
  if (batch_max_runs_out != NULL) {
    *batch_max_runs_out = 0u;
  }
  if (batch_max_deps_out != NULL) {
    *batch_max_deps_out = 0u;
  }
  if (batch_max_work_out != NULL) {
    *batch_max_work_out = 0.0;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Llen == NULL ||
      group_ptr == NULL || group_runs == NULL || group_rows == NULL ||
      plan_current == NULL || plan_dep == NULL ||
      batch_count_out == NULL ||
      batch_run_count_out == NULL ||
      batch_run_rows_out == NULL ||
      batch_dep_count_out == NULL ||
      batch_work_out == NULL ||
      batch_max_runs_out == NULL ||
      batch_max_deps_out == NULL ||
      batch_max_work_out == NULL) {
    return 0;
  }
  if (group_count == 0u || group_run_count == 0u || run_count == 0u ||
      max_group_runs < 2u) {
    return 1;
  }

  const size_t max_runs = (size_t)max_group_runs;
  if ((UF_long)max_runs != max_group_runs || max_runs > SIZE_MAX / 2u) {
    return 0;
  }
  size_t bucket_count = 4u;
  const size_t wanted_buckets = max_runs * 2u;
  while (bucket_count < wanted_buckets) {
    if (bucket_count > SIZE_MAX / 2u) {
      return 0;
    }
    bucket_count *= 2u;
  }
  if (bucket_count > SIZE_MAX / sizeof(uint64_t) ||
      bucket_count > SIZE_MAX / sizeof(UF_long) ||
      bucket_count > SIZE_MAX / sizeof(double) ||
      bucket_count > SIZE_MAX / sizeof(unsigned char) ||
      bucket_count > SIZE_MAX / sizeof(const UF_long *)) {
    return 0;
  }

  uint64_t *bucket_hash =
    (uint64_t *)malloc(bucket_count * sizeof(*bucket_hash));
  const UF_long **bucket_ui =
    (const UF_long **)malloc(bucket_count * sizeof(*bucket_ui));
  UF_long *bucket_block_start =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_block_start));
  UF_long *bucket_prefix_len =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_prefix_len));
  UF_long *bucket_runs =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_runs));
  UF_long *bucket_run_rows =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_run_rows));
  UF_long *bucket_deps =
    (UF_long *)malloc(bucket_count * sizeof(*bucket_deps));
  double *bucket_work =
    (double *)malloc(bucket_count * sizeof(*bucket_work));
  unsigned char *bucket_used =
    (unsigned char *)malloc(bucket_count * sizeof(*bucket_used));
  if (bucket_hash == NULL || bucket_ui == NULL ||
      bucket_block_start == NULL || bucket_prefix_len == NULL ||
      bucket_runs == NULL || bucket_run_rows == NULL ||
      bucket_deps == NULL || bucket_work == NULL || bucket_used == NULL) {
    free(bucket_hash);
    free(bucket_ui);
    free(bucket_block_start);
    free(bucket_prefix_len);
    free(bucket_runs);
    free(bucket_run_rows);
    free(bucket_deps);
    free(bucket_work);
    free(bucket_used);
    return 0;
  }

  UF_long batch_count = 0u;
  UF_long batch_run_count = 0u;
  UF_long batch_run_rows = 0u;
  UF_long batch_dep_count = 0u;
  double batch_work = 0.0;
  UF_long batch_max_runs = 0u;
  UF_long batch_max_deps = 0u;
  double batch_max_work = 0.0;
  int ok = 1;
  for (UF_long group = 0u; ok && group < group_count; ++group) {
    const UF_long begin = group_ptr[group];
    const UF_long end = group_ptr[group + 1u];
    if (begin > end || end > group_run_count) {
      ok = 0;
      break;
    }
    const UF_long runs = end - begin;
    if (runs < 2u) {
      continue;
    }
    const size_t group_runs_size = (size_t)runs;
    if ((UF_long)group_runs_size != runs || group_runs_size > max_runs ||
        group_runs_size > SIZE_MAX / 2u) {
      ok = 0;
      break;
    }
    size_t active_buckets = 4u;
    const size_t wanted = group_runs_size * 2u;
    while (active_buckets < wanted) {
      active_buckets *= 2u;
    }
    memset(bucket_used, 0, active_buckets * sizeof(*bucket_used));
    const UF_long rows = group_rows[group];
    for (UF_long pos = begin; ok && pos < end; ++pos) {
      const UF_long run = group_runs[pos];
      if (run >= run_count) {
        ok = 0;
        break;
      }
      UF_long prefix_len = 0u;
      UF_long block_start = 0u;
      const UF_long *ui = NULL;
      if (!kls_supernode_consumer_plan_run_dep_position(
            solver, plan_current, plan_dep, run_count, run,
            &prefix_len, &block_start, &ui)) {
        continue;
      }
      if (prefix_len == 0u) {
        continue;
      }
      uint64_t hash =
        kls_mix_u64((uint64_t)block_start ^
                    (kls_mix_u64((uint64_t)prefix_len) +
                     UINT64_C(0x9e3779b97f4a7c15)));
      double run_work = 0.0;
      for (UF_long prefix_pos = 0u; prefix_pos < prefix_len; ++prefix_pos) {
        if (ui == NULL || ui[prefix_pos] > UF_long_max - block_start) {
          ok = 0;
          break;
        }
        const UF_long dep = block_start + ui[prefix_pos];
        if (dep >= solver->n || dep >= plan_current[run]) {
          ok = 0;
          break;
        }
        hash ^= kls_mix_u64((uint64_t)ui[prefix_pos] +
                            UINT64_C(0xbf58476d1ce4e5b9) +
                            (hash << 6) + (hash >> 2));
        run_work += 1.0 + (double)solver->numeric->Llen[dep];
      }
      if (!ok) {
        break;
      }
      size_t slot = (size_t)hash & (active_buckets - 1u);
      while (bucket_used[slot] &&
             (bucket_hash[slot] != hash ||
              !kls_same_supernode_consumer_plan_prefix(
                bucket_block_start[slot], bucket_ui[slot],
                bucket_prefix_len[slot], block_start, ui, prefix_len))) {
        slot = (slot + 1u) & (active_buckets - 1u);
      }
      if (!bucket_used[slot]) {
        bucket_used[slot] = 1u;
        bucket_hash[slot] = hash;
        bucket_ui[slot] = ui;
        bucket_block_start[slot] = block_start;
        bucket_prefix_len[slot] = prefix_len;
        bucket_runs[slot] = 0u;
        bucket_run_rows[slot] = 0u;
        bucket_deps[slot] = 0u;
        bucket_work[slot] = 0.0;
      }
      if (bucket_runs[slot] == UF_long_max ||
          rows > UF_long_max - bucket_run_rows[slot] ||
          prefix_len > UF_long_max - bucket_deps[slot]) {
        ok = 0;
        break;
      }
      bucket_runs[slot]++;
      bucket_run_rows[slot] += rows;
      bucket_deps[slot] += prefix_len;
      bucket_work[slot] += run_work;
    }
    for (size_t slot = 0u; ok && slot < active_buckets; ++slot) {
      if (!bucket_used[slot] || bucket_runs[slot] < 2u) {
        continue;
      }
      if (batch_count == UF_long_max ||
          bucket_runs[slot] > UF_long_max - batch_run_count ||
          bucket_run_rows[slot] > UF_long_max - batch_run_rows ||
          bucket_deps[slot] > UF_long_max - batch_dep_count) {
        ok = 0;
        break;
      }
      batch_count++;
      batch_run_count += bucket_runs[slot];
      batch_run_rows += bucket_run_rows[slot];
      batch_dep_count += bucket_deps[slot];
      batch_work += bucket_work[slot];
      if (bucket_runs[slot] > batch_max_runs) {
        batch_max_runs = bucket_runs[slot];
      }
      if (bucket_prefix_len[slot] > batch_max_deps) {
        batch_max_deps = bucket_prefix_len[slot];
      }
      if (bucket_work[slot] > batch_max_work) {
        batch_max_work = bucket_work[slot];
      }
    }
  }

  free(bucket_hash);
  free(bucket_ui);
  free(bucket_block_start);
  free(bucket_prefix_len);
  free(bucket_runs);
  free(bucket_run_rows);
  free(bucket_deps);
  free(bucket_work);
  free(bucket_used);
  if (!ok) {
    return 0;
  }
  *batch_count_out = batch_count;
  *batch_run_count_out = batch_run_count;
  *batch_run_rows_out = batch_run_rows;
  *batch_dep_count_out = batch_dep_count;
  *batch_work_out = batch_work;
  *batch_max_runs_out = batch_max_runs;
  *batch_max_deps_out = batch_max_deps;
  *batch_max_work_out = batch_max_work;
  return 1;
}

typedef struct {
  UF_long large_panel_count;
  UF_long large_panel_rows;
  UF_long large_panel_prefix_rows;
  UF_long large_panel_max_width;
  UF_long candidate_run_count;
  UF_long candidate_run_rows;
  UF_long prefix_run_count;
  UF_long prefix_run_rows;
  double prefix_update_work;
  UF_long crossing_run_count;
  UF_long crossing_run_rows;
  UF_long prefix_advance_run_count;
  UF_long prefix_advance_run_rows;
  UF_long prefix_advance_dep_count;
  double prefix_advance_work;
  UF_long prefix_payoff_run_count;
  UF_long prefix_payoff_run_rows;
  double prefix_payoff_update_work;
  double prefix_payoff_advance_work;
  UF_long prefix_panel_count;
  UF_long prefix_panel_run_count;
  UF_long prefix_panel_run_rows;
  UF_long prefix_panel_advance_dep_count;
  double prefix_panel_update_work;
  double prefix_panel_advance_work;
  UF_long prefix_panel_max_runs;
  UF_long prefix_panel_payoff_count;
  UF_long prefix_panel_payoff_run_count;
  UF_long prefix_panel_payoff_run_rows;
  double prefix_panel_payoff_update_work;
  double prefix_panel_payoff_advance_work;
  UF_long prefix_panel_payoff_subset_count;
  UF_long prefix_panel_payoff_subset_run_count;
  UF_long prefix_panel_payoff_subset_run_rows;
  double prefix_panel_payoff_subset_update_work;
  double prefix_panel_payoff_subset_advance_work;
  UF_long prefix_panel_payoff_subset_max_runs;
  UF_long prefix_panel_payoff_subset_current_count;
  UF_long prefix_panel_payoff_subset_multi_current_count;
  UF_long prefix_panel_payoff_subset_max_currents;
} kls_supernode_algorithm5_split_stats;

static int kls_count_refactor_supernode_algorithm5_split_opportunities(
  const kls_solver *solver,
  const UF_long *consumer_start,
  const UF_long *consumer_end,
  const UF_long *plan_ptr,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  const UF_long *plan_rows,
  const UF_long *plan_panel_start,
  const UF_long *plan_panel_offset,
  UF_long run_count,
  kls_supernode_algorithm5_split_stats *stats) {
  if (stats != NULL) {
    memset(stats, 0, sizeof(*stats));
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Llen == NULL ||
      consumer_start == NULL || consumer_end == NULL || stats == NULL) {
    return 0;
  }

  UF_long producer_suffix_rows = 1u;
  if (solver->options.threads > 1) {
    producer_suffix_rows = (UF_long)solver->options.threads;
  }
  if (producer_suffix_rows > UF_long_max / 2u) {
    return 0;
  }
  const UF_long min_split_width = 2u * producer_suffix_rows;

  for (UF_long panel = 0u; panel < solver->n; ++panel) {
    if (consumer_start[panel] != panel) {
      continue;
    }
    const UF_long end = consumer_end[panel];
    if (end <= panel || end > solver->n) {
      continue;
    }
    const UF_long width = end - panel;
    if (width < min_split_width) {
      continue;
    }
    const UF_long prefix_rows = width - producer_suffix_rows;
    if (stats->large_panel_count == UF_long_max ||
        width > UF_long_max - stats->large_panel_rows ||
        prefix_rows > UF_long_max - stats->large_panel_prefix_rows) {
      return 0;
    }
    stats->large_panel_count++;
    stats->large_panel_rows += width;
    stats->large_panel_prefix_rows += prefix_rows;
    if (width > stats->large_panel_max_width) {
      stats->large_panel_max_width = width;
    }
  }

  if (run_count == 0u) {
    return 1;
  }
  if (plan_ptr == NULL || plan_current == NULL || plan_dep == NULL ||
      plan_rows == NULL || plan_panel_start == NULL ||
      plan_panel_offset == NULL) {
    return 0;
  }

  for (UF_long panel = 0u; panel < solver->n; ++panel) {
    if (consumer_start[panel] != panel) {
      continue;
    }
    const UF_long end = consumer_end[panel];
    if (end <= panel || end > solver->n) {
      continue;
    }
    const UF_long width = end - panel;
    if (width < min_split_width) {
      continue;
    }
    const UF_long begin_run = plan_ptr[panel];
    const UF_long end_run = plan_ptr[panel + 1u];
    if (begin_run > end_run || end_run > run_count) {
      return 0;
    }

    const UF_long prefix_limit = width - producer_suffix_rows;
    UF_long panel_prefix_run_count = 0u;
    UF_long panel_prefix_run_rows = 0u;
    UF_long panel_prefix_advance_dep_count = 0u;
    double panel_prefix_update_work = 0.0;
    double panel_prefix_advance_work = 0.0;
    UF_long panel_payoff_subset_run_count = 0u;
    UF_long panel_payoff_subset_run_rows = 0u;
    double panel_payoff_subset_update_work = 0.0;
    double panel_payoff_subset_advance_work = 0.0;
    UF_long panel_payoff_subset_current_count = 0u;
    UF_long panel_payoff_subset_last_current = KLS_KLU_EMPTY;
    for (UF_long run = begin_run; run < end_run; ++run) {
      if (plan_panel_start[run] != panel) {
        return 0;
      }
      const UF_long rows = plan_rows[run];
      const UF_long offset = plan_panel_offset[run];
      if (rows == 0u || offset >= width || rows > width - offset) {
        continue;
      }
      if (stats->candidate_run_count == UF_long_max ||
          rows > UF_long_max - stats->candidate_run_rows) {
        return 0;
      }
      stats->candidate_run_count++;
      stats->candidate_run_rows += rows;

      if (offset >= prefix_limit) {
        continue;
      }
      UF_long prefix_rows = prefix_limit - offset;
      if (prefix_rows > rows) {
        prefix_rows = rows;
      }
      if (prefix_rows == 0u) {
        continue;
      }
      if (stats->prefix_run_count == UF_long_max ||
          prefix_rows > UF_long_max - stats->prefix_run_rows) {
        return 0;
      }
      const UF_long dep = plan_dep[run];
      if (dep >= solver->n || prefix_rows > solver->n - dep) {
        return 0;
      }
      stats->prefix_run_count++;
      stats->prefix_run_rows += prefix_rows;
      double run_update_work = 0.0;
      for (UF_long local = 0u; local < prefix_rows; ++local) {
        run_update_work += 1.0 + (double)solver->numeric->Llen[dep + local];
      }
      stats->prefix_update_work += run_update_work;

      UF_long run_advance_deps = 0u;
      double run_advance_work = 0.0;
      if (kls_supernode_consumer_plan_run_advance_cost(
            solver, plan_current, plan_dep, run_count, run,
            &run_advance_deps, &run_advance_work)) {
        if (stats->prefix_advance_run_count == UF_long_max ||
            prefix_rows > UF_long_max -
                            stats->prefix_advance_run_rows ||
            run_advance_deps > UF_long_max -
                                  stats->prefix_advance_dep_count ||
            panel_prefix_run_count == UF_long_max ||
            prefix_rows > UF_long_max - panel_prefix_run_rows ||
            run_advance_deps > UF_long_max -
                                  panel_prefix_advance_dep_count) {
          return 0;
        }
        stats->prefix_advance_run_count++;
        stats->prefix_advance_run_rows += prefix_rows;
        stats->prefix_advance_dep_count += run_advance_deps;
        stats->prefix_advance_work += run_advance_work;
        if (run_update_work >= run_advance_work) {
          if (stats->prefix_payoff_run_count == UF_long_max ||
              prefix_rows > UF_long_max -
                              stats->prefix_payoff_run_rows ||
              panel_payoff_subset_run_count == UF_long_max ||
              prefix_rows > UF_long_max -
                              panel_payoff_subset_run_rows) {
            return 0;
          }
          stats->prefix_payoff_run_count++;
          stats->prefix_payoff_run_rows += prefix_rows;
          stats->prefix_payoff_update_work += run_update_work;
          stats->prefix_payoff_advance_work += run_advance_work;
          const UF_long current = plan_current[run];
          if (current >= solver->n) {
            return 0;
          }
          if (current != panel_payoff_subset_last_current) {
            if (panel_payoff_subset_current_count == UF_long_max) {
              return 0;
            }
            panel_payoff_subset_current_count++;
            panel_payoff_subset_last_current = current;
          }
          panel_payoff_subset_run_count++;
          panel_payoff_subset_run_rows += prefix_rows;
          panel_payoff_subset_update_work += run_update_work;
          panel_payoff_subset_advance_work += run_advance_work;
        }
        panel_prefix_run_count++;
        panel_prefix_run_rows += prefix_rows;
        panel_prefix_advance_dep_count += run_advance_deps;
        panel_prefix_update_work += run_update_work;
        panel_prefix_advance_work += run_advance_work;
      }

      if (rows > UF_long_max - offset) {
        return 0;
      }
      if (offset + rows > prefix_limit) {
        if (stats->crossing_run_count == UF_long_max ||
            rows > UF_long_max - stats->crossing_run_rows) {
          return 0;
        }
        stats->crossing_run_count++;
        stats->crossing_run_rows += rows;
      }
    }
    if (panel_prefix_run_count >= 2u) {
      if (stats->prefix_panel_count == UF_long_max ||
          panel_prefix_run_count > UF_long_max -
                                      stats->prefix_panel_run_count ||
          panel_prefix_run_rows > UF_long_max -
                                    stats->prefix_panel_run_rows ||
          panel_prefix_advance_dep_count >
            UF_long_max - stats->prefix_panel_advance_dep_count) {
        return 0;
      }
      stats->prefix_panel_count++;
      stats->prefix_panel_run_count += panel_prefix_run_count;
      stats->prefix_panel_run_rows += panel_prefix_run_rows;
      stats->prefix_panel_advance_dep_count +=
        panel_prefix_advance_dep_count;
      stats->prefix_panel_update_work += panel_prefix_update_work;
      stats->prefix_panel_advance_work += panel_prefix_advance_work;
      if (panel_prefix_run_count > stats->prefix_panel_max_runs) {
        stats->prefix_panel_max_runs = panel_prefix_run_count;
      }
      if (panel_prefix_update_work >= panel_prefix_advance_work) {
        if (stats->prefix_panel_payoff_count == UF_long_max ||
            panel_prefix_run_count > UF_long_max -
                                       stats
                                         ->prefix_panel_payoff_run_count ||
            panel_prefix_run_rows > UF_long_max -
                                      stats
                                        ->prefix_panel_payoff_run_rows) {
          return 0;
        }
        stats->prefix_panel_payoff_count++;
        stats->prefix_panel_payoff_run_count += panel_prefix_run_count;
        stats->prefix_panel_payoff_run_rows += panel_prefix_run_rows;
        stats->prefix_panel_payoff_update_work += panel_prefix_update_work;
        stats->prefix_panel_payoff_advance_work += panel_prefix_advance_work;
      }
    }
    if (panel_payoff_subset_run_count >= 2u) {
      if (stats->prefix_panel_payoff_subset_count == UF_long_max ||
          panel_payoff_subset_run_count >
            UF_long_max - stats->prefix_panel_payoff_subset_run_count ||
          panel_payoff_subset_run_rows >
            UF_long_max - stats->prefix_panel_payoff_subset_run_rows ||
          panel_payoff_subset_current_count >
            UF_long_max - stats
                            ->prefix_panel_payoff_subset_current_count) {
        return 0;
      }
      stats->prefix_panel_payoff_subset_count++;
      stats->prefix_panel_payoff_subset_run_count +=
        panel_payoff_subset_run_count;
      stats->prefix_panel_payoff_subset_run_rows +=
        panel_payoff_subset_run_rows;
      stats->prefix_panel_payoff_subset_current_count +=
        panel_payoff_subset_current_count;
      if (panel_payoff_subset_current_count >= 2u) {
        if (stats->prefix_panel_payoff_subset_multi_current_count ==
            UF_long_max) {
          return 0;
        }
        stats->prefix_panel_payoff_subset_multi_current_count++;
      }
      stats->prefix_panel_payoff_subset_update_work +=
        panel_payoff_subset_update_work;
      stats->prefix_panel_payoff_subset_advance_work +=
        panel_payoff_subset_advance_work;
      if (panel_payoff_subset_run_count >
          stats->prefix_panel_payoff_subset_max_runs) {
        stats->prefix_panel_payoff_subset_max_runs =
          panel_payoff_subset_run_count;
      }
      if (panel_payoff_subset_current_count >
          stats->prefix_panel_payoff_subset_max_currents) {
        stats->prefix_panel_payoff_subset_max_currents =
          panel_payoff_subset_current_count;
      }
    }
  }

  return 1;
}

static int kls_refactor_supernode_algorithm5_run_prefix_rows(
  const kls_solver *solver,
  const UF_long *consumer_start,
  const UF_long *consumer_end,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  const UF_long *plan_rows,
  const UF_long *plan_panel_start,
  const UF_long *plan_panel_offset,
  UF_long run_count,
  UF_long run,
  UF_long *prefix_rows_out) {
  if (prefix_rows_out != NULL) {
    *prefix_rows_out = 0u;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Llen == NULL || consumer_start == NULL ||
      consumer_end == NULL || plan_current == NULL || plan_dep == NULL ||
      plan_rows == NULL || plan_panel_start == NULL ||
      plan_panel_offset == NULL || prefix_rows_out == NULL ||
      run >= run_count) {
    return 0;
  }
  UF_long producer_suffix_rows = 1u;
  if (solver->options.threads > 1) {
    producer_suffix_rows = (UF_long)solver->options.threads;
  }
  if (producer_suffix_rows > UF_long_max / 2u) {
    return 0;
  }
  const UF_long panel = plan_panel_start[run];
  const UF_long rows = plan_rows[run];
  const UF_long offset = plan_panel_offset[run];
  if (panel >= solver->n || rows == 0u ||
      consumer_start[panel] != panel) {
    return 0;
  }
  const UF_long end = consumer_end[panel];
  if (end <= panel || end > solver->n) {
    return 0;
  }
  const UF_long width = end - panel;
  if (width < 2u * producer_suffix_rows || offset >= width ||
      rows > width - offset) {
    return 0;
  }
  const UF_long prefix_limit = width - producer_suffix_rows;
  if (offset >= prefix_limit) {
    return 0;
  }
  UF_long prefix_rows = prefix_limit - offset;
  if (prefix_rows > rows) {
    prefix_rows = rows;
  }
  if (prefix_rows == 0u) {
    return 0;
  }
  const UF_long dep = plan_dep[run];
  if (dep >= solver->n || prefix_rows > solver->n - dep) {
    return 0;
  }
  *prefix_rows_out = prefix_rows;
  return 1;
}

static int kls_refactor_supernode_algorithm5_run_target_entries(
  const kls_solver *solver,
  const UF_long *plan_dep,
  const UF_long *plan_panel_start,
  const UF_long *plan_panel_offset,
  UF_long run_count,
  UF_long run,
  UF_long group_pattern_width,
  UF_long prefix_rows,
  UF_long *target_entries_out) {
  if (target_entries_out != NULL) {
    *target_entries_out = 0u;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Llen == NULL || solver->refactor_l_indices == NULL ||
      plan_dep == NULL || plan_panel_start == NULL ||
      plan_panel_offset == NULL || target_entries_out == NULL ||
      run >= run_count || prefix_rows == 0u || group_pattern_width == 0u) {
    return 0;
  }
  const UF_long panel_start = plan_panel_start[run];
  const UF_long panel_offset = plan_panel_offset[run];
  const UF_long dep = plan_dep[run];
  if (panel_start >= solver->n || group_pattern_width > solver->n ||
      panel_offset >= group_pattern_width ||
      prefix_rows > group_pattern_width - panel_offset ||
      panel_start > solver->n - group_pattern_width ||
      panel_offset > UF_long_max - prefix_rows ||
      dep != panel_start + panel_offset) {
    return 0;
  }

  const UF_long run_end = panel_offset + prefix_rows;
  const UF_long dense_suffix = group_pattern_width - run_end;
  if (prefix_rows != 0u && dense_suffix > UF_long_max / prefix_rows) {
    return 0;
  }
  UF_long target_entries = prefix_rows * dense_suffix;

  UF_long k1 = 0u;
  UF_long block_size = 0u;
  UF_long local_start = 0u;
  if (!kls_refactor_supernode_panel_block_info(
        solver, panel_start, panel_start + group_pattern_width, &k1,
        &block_size, &local_start)) {
    *target_entries_out = target_entries;
    return 1;
  }
  (void)k1;
  if (local_start > block_size ||
      group_pattern_width > block_size - local_start) {
    *target_entries_out = target_entries;
    return 1;
  }
  const UF_long skip_begin = local_start;
  const UF_long skip_end = local_start + group_pattern_width;
  for (UF_long local = 0u; local < prefix_rows; ++local) {
    const UF_long col = dep + local;
    if (col >= solver->n) {
      return 0;
    }
    const UF_long *rows = solver->refactor_l_indices[col];
    const UF_long length = solver->numeric->Llen[col];
    if (rows == NULL && length > 0u) {
      return 0;
    }
    for (UF_long p = 0u; p < length; ++p) {
      const UF_long row = rows[p];
      if (row >= block_size || row < skip_begin || row >= skip_end) {
        if (target_entries == UF_long_max) {
          return 0;
        }
        target_entries++;
      }
    }
  }

  *target_entries_out = target_entries;
  return 1;
}

static int kls_refactor_supernode_algorithm5_next_target_stamp(
  UF_long *stamp_workspace,
  UF_long stamp_workspace_size,
  UF_long *stamp_io,
  UF_long *stamp_out) {
  if (stamp_out != NULL) {
    *stamp_out = 0u;
  }
  if (stamp_workspace == NULL || stamp_workspace_size == 0u ||
      stamp_io == NULL || stamp_out == NULL) {
    return 0;
  }
  if (*stamp_io == UF_long_max) {
    memset(stamp_workspace, 0,
           (size_t)stamp_workspace_size * sizeof(*stamp_workspace));
    *stamp_io = 1u;
  } else {
    (*stamp_io)++;
    if (*stamp_io == 0u) {
      *stamp_io = 1u;
    }
  }
  *stamp_out = *stamp_io;
  return 1;
}

static int kls_refactor_supernode_algorithm5_run_target_slots(
  const kls_solver *solver,
  const UF_long *plan_dep,
  const UF_long *plan_panel_start,
  const UF_long *plan_panel_offset,
  UF_long run_count,
  UF_long run,
  UF_long group_pattern_width,
  UF_long prefix_rows,
  UF_long *stamp_workspace,
  UF_long stamp_workspace_size,
  UF_long *stamp_io,
  UF_long *target_cols,
  UF_long target_col_capacity,
  UF_long *target_slots_out) {
  if (target_slots_out != NULL) {
    *target_slots_out = 0u;
  }
  if (solver == NULL || solver->numeric == NULL ||
      solver->numeric->Llen == NULL || solver->refactor_l_indices == NULL ||
      plan_dep == NULL || plan_panel_start == NULL ||
      plan_panel_offset == NULL || target_slots_out == NULL ||
      run >= run_count || prefix_rows == 0u || group_pattern_width == 0u ||
      stamp_workspace == NULL || stamp_workspace_size == 0u ||
      stamp_io == NULL) {
    return 0;
  }
  const UF_long panel_start = plan_panel_start[run];
  const UF_long panel_offset = plan_panel_offset[run];
  const UF_long dep = plan_dep[run];
  if (panel_start >= solver->n || group_pattern_width > solver->n ||
      panel_offset >= group_pattern_width ||
      prefix_rows > group_pattern_width - panel_offset ||
      panel_start > solver->n - group_pattern_width ||
      panel_offset > UF_long_max - prefix_rows ||
      dep != panel_start + panel_offset) {
    return 0;
  }

  UF_long k1 = 0u;
  UF_long block_size = 0u;
  UF_long local_start = 0u;
  if (!kls_refactor_supernode_panel_block_info(
        solver, panel_start, panel_start + group_pattern_width, &k1,
        &block_size, &local_start)) {
    return 0;
  }
  (void)k1;
  if (local_start > block_size ||
      group_pattern_width > block_size - local_start ||
      block_size > stamp_workspace_size) {
    return 0;
  }
  const UF_long skip_begin = local_start;
  const UF_long skip_end = local_start + group_pattern_width;
  const UF_long run_end = panel_offset + prefix_rows;
  UF_long target_slots = 0u;
  for (UF_long target = run_end; target < group_pattern_width; ++target) {
    const UF_long row = local_start + target;
    if (row >= block_size || row >= stamp_workspace_size ||
        target_slots == UF_long_max) {
      return 0;
    }
    if (target_cols != NULL) {
      if (target_slots >= target_col_capacity) {
        return 0;
      }
      target_cols[target_slots] = row;
    }
    target_slots++;
  }

  UF_long stamp = 0u;
  if (!kls_refactor_supernode_algorithm5_next_target_stamp(
        stamp_workspace, stamp_workspace_size, stamp_io, &stamp)) {
    return 0;
  }
  for (UF_long local = 0u; local < prefix_rows; ++local) {
    const UF_long col = dep + local;
    if (col >= solver->n) {
      return 0;
    }
    const UF_long *rows = solver->refactor_l_indices[col];
    const UF_long length = solver->numeric->Llen[col];
    if (rows == NULL && length > 0u) {
      return 0;
    }
    for (UF_long p = 0u; p < length; ++p) {
      const UF_long row = rows[p];
      if (row >= stamp_workspace_size) {
        return 0;
      }
      if (row >= skip_begin && row < skip_end) {
        continue;
      }
      if (stamp_workspace[row] == stamp) {
        continue;
      }
      if (target_slots == UF_long_max) {
        return 0;
      }
      stamp_workspace[row] = stamp;
      if (target_cols != NULL) {
        if (target_slots >= target_col_capacity) {
          return 0;
        }
        target_cols[target_slots] = row;
      }
      target_slots++;
    }
  }

  *target_slots_out = target_slots;
  return 1;
}

static int kls_refactor_supernode_algorithm5_run_advance_slots(
  const kls_solver *solver,
  const UF_long *plan_current,
  UF_long run_count,
  UF_long run,
  UF_long advance_deps,
  UF_long *stamp_workspace,
  UF_long stamp_workspace_size,
  UF_long *stamp_io,
  UF_long *advance_cols,
  UF_long advance_col_capacity,
  UF_long *advance_slots_out) {
  if (advance_slots_out != NULL) {
    *advance_slots_out = 0u;
  }
  if (solver == NULL || solver->symbolic == NULL ||
      solver->symbolic->R == NULL || solver->numeric == NULL ||
      solver->numeric->Ulen == NULL || solver->numeric->Llen == NULL ||
      (solver->refactor_u_indices == NULL &&
       solver->refactor_u_indices32 == NULL) ||
      (solver->refactor_l_indices == NULL &&
       solver->refactor_l_indices32 == NULL) ||
      plan_current == NULL || run >= run_count ||
      stamp_workspace == NULL || stamp_workspace_size == 0u ||
      stamp_io == NULL || advance_slots_out == NULL) {
    return 0;
  }
  if (advance_deps == 0u) {
    return 1;
  }

  const UF_long current = plan_current[run];
  if (current >= solver->n) {
    return 0;
  }
  UF_long block = KLS_KLU_EMPTY;
  if (solver->symbolic->nblocks == 1u) {
    block = 0u;
  } else if (solver->refactor_col_block != NULL) {
    block = solver->refactor_col_block[current];
  } else {
    block = kls_block_for_pivot(solver, current);
  }
  if (block == KLS_KLU_EMPTY || block >= solver->symbolic->nblocks) {
    return 0;
  }
  const UF_long k1 = solver->symbolic->R[block];
  const UF_long k2 = solver->symbolic->R[block + 1u];
  if (k2 < k1 || current < k1 || current >= k2) {
    return 0;
  }
  const UF_long block_size = k2 - k1;
  if (block_size == 0u || block_size > stamp_workspace_size ||
      advance_deps > solver->numeric->Ulen[current]) {
    return 0;
  }
  const UF_long *ui =
    solver->refactor_u_indices != NULL ? solver->refactor_u_indices[current]
                                       : NULL;
  const int32_t *ui32 =
    solver->refactor_u_indices32 != NULL
      ? solver->refactor_u_indices32[current] : NULL;
  if (ui == NULL && ui32 == NULL) {
    return 0;
  }

  UF_long stamp = 0u;
  if (!kls_refactor_supernode_algorithm5_next_target_stamp(
        stamp_workspace, stamp_workspace_size, stamp_io, &stamp)) {
    return 0;
  }

  UF_long advance_slots = 0u;
  for (UF_long p = 0u; p < advance_deps; ++p) {
    const UF_long dep_local = ui32 != NULL ? (UF_long)ui32[p] : ui[p];
    if (dep_local >= block_size || dep_local > UF_long_max - k1) {
      return 0;
    }
    const UF_long dep_global = k1 + dep_local;
    if (dep_global >= solver->n) {
      return 0;
    }
    if (stamp_workspace[dep_local] != stamp) {
      stamp_workspace[dep_local] = stamp;
      if (advance_cols != NULL) {
        if (advance_slots >= advance_col_capacity) {
          return 0;
        }
        advance_cols[advance_slots] = dep_local;
      }
      advance_slots++;
    }

    const UF_long length = solver->numeric->Llen[dep_global];
    const int32_t *rows32 =
      solver->refactor_l_indices32 != NULL
        ? solver->refactor_l_indices32[dep_global] : NULL;
    const UF_long *rows =
      rows32 == NULL && solver->refactor_l_indices != NULL
        ? solver->refactor_l_indices[dep_global] : NULL;
    if (length > 0u && rows32 == NULL && rows == NULL) {
      return 0;
    }
    for (UF_long q = 0u; q < length; ++q) {
      const UF_long row = rows32 != NULL ? (UF_long)rows32[q] : rows[q];
      if (row >= block_size) {
        return 0;
      }
      if (stamp_workspace[row] == stamp) {
        continue;
      }
      stamp_workspace[row] = stamp;
      if (advance_slots == UF_long_max) {
        return 0;
      }
      if (advance_cols != NULL) {
        if (advance_slots >= advance_col_capacity) {
          return 0;
        }
        advance_cols[advance_slots] = row;
      }
      advance_slots++;
    }
  }

  *advance_slots_out = advance_slots;
  return 1;
}

static int kls_refactor_supernode_algorithm5_run_payoff(
  const kls_solver *solver,
  const UF_long *consumer_start,
  const UF_long *consumer_end,
  const UF_long *plan_current,
  const UF_long *plan_dep,
  const UF_long *plan_rows,
  const UF_long *plan_panel_start,
  const UF_long *plan_panel_offset,
  UF_long run_count,
  UF_long run) {
  UF_long prefix_rows = 0u;
  if (!kls_refactor_supernode_algorithm5_run_prefix_rows(
        solver, consumer_start, consumer_end, plan_current, plan_dep,
        plan_rows, plan_panel_start, plan_panel_offset, run_count, run,
        &prefix_rows)) {
    return 0;
  }
  const UF_long dep = plan_dep[run];
  double update_work = 0.0;
  for (UF_long local = 0u; local < prefix_rows; ++local) {
    update_work += 1.0 + (double)solver->numeric->Llen[dep + local];
  }
  UF_long advance_deps = 0u;
  double advance_work = 0.0;
  if (!kls_supernode_consumer_plan_run_advance_cost(
        solver, plan_current, plan_dep, run_count, run,
        &advance_deps, &advance_work)) {
    return 0;
  }
  (void)advance_deps;
  return update_work >= advance_work;
}

