static int kls_algorithm5_payoff_current_final_dep(
  const kls_solver *solver,
  UF_long current,
  UF_long *final_dep_out) {
  if (final_dep_out != NULL) {
    *final_dep_out = KLS_KLU_EMPTY;
  }
  if (solver == NULL || solver->symbolic == NULL ||
      solver->symbolic->R == NULL || solver->numeric == NULL ||
      solver->numeric->Ulen == NULL ||
      (solver->refactor_u_indices == NULL &&
       solver->refactor_u_indices32 == NULL) ||
      final_dep_out == NULL || current >= solver->n) {
    return 0;
  }
  UF_long block = KLS_KLU_EMPTY;
  if (solver->symbolic->nblocks == 1u) {
    block = 0u;
  } else if (solver->refactor_col_block != NULL) {
    block = solver->refactor_col_block[current];
  } else {
    block = kls_block_for_pivot(solver, current);
  }
  if (block == KLS_KLU_EMPTY || block >= solver->symbolic->nblocks) {
    return 0;
  }
  const UF_long k1 = solver->symbolic->R[block];
  const UF_long k2 = solver->symbolic->R[block + 1u];
  if (k2 <= k1 || current < k1 || current >= k2) {
    return 0;
  }
  const UF_long local_current = current - k1;
  const UF_long ulen = solver->numeric->Ulen[current];
  if (ulen == 0u) {
    return 0;
  }
  const UF_long *ui =
    solver->refactor_u_indices != NULL
      ? solver->refactor_u_indices[current] : NULL;
  const int32_t *ui32 =
    solver->refactor_u_indices32 != NULL
      ? solver->refactor_u_indices32[current] : NULL;
  if (ui == NULL && ui32 == NULL) {
    return 0;
  }
  const UF_long dep_local =
    ui32 != NULL ? (UF_long)ui32[ulen - 1u] : ui[ulen - 1u];
  if (dep_local >= local_current || dep_local > UF_long_max - k1) {
    return 0;
  }
  const UF_long dep = k1 + dep_local;
  if (dep >= current || dep >= solver->n) {
    return 0;
  }
  *final_dep_out = dep;
  return 1;
}

static int kls_algorithm5_payoff_current_slot_single_run(
  const kls_solver *solver,
  UF_long current_slot,
  UF_long *current_out,
  UF_long *run_out) {
  if (current_out != NULL) {
    *current_out = KLS_KLU_EMPTY;
  }
  if (run_out != NULL) {
    *run_out = KLS_KLU_EMPTY;
  }
  if (solver == NULL || current_out == NULL || run_out == NULL ||
      current_slot >=
        solver->refactor_supernode_algorithm5_payoff_group_current_total ||
      solver->refactor_supernode_algorithm5_payoff_group_currents == NULL ||
      solver->refactor_supernode_algorithm5_payoff_group_current_run_ptr ==
        NULL ||
      solver->refactor_supernode_algorithm5_payoff_group_current_runs ==
        NULL ||
      solver->refactor_supernode_algorithm5_payoff_group_ptr == NULL ||
      solver->refactor_supernode_algorithm5_payoff_run_selected == NULL ||
      current_slot + 1u >
        solver->refactor_supernode_algorithm5_payoff_group_current_total) {
    return 0;
  }
  const UF_long current =
    solver->refactor_supernode_algorithm5_payoff_group_currents[current_slot];
  const UF_long run_begin =
    solver->refactor_supernode_algorithm5_payoff_group_current_run_ptr[
      current_slot];
  const UF_long run_end =
    solver->refactor_supernode_algorithm5_payoff_group_current_run_ptr[
      current_slot + 1u];
  if (current >= solver->n || run_begin > run_end ||
      run_end >
        solver->refactor_supernode_algorithm5_payoff_group_ptr[
          solver->refactor_supernode_algorithm5_payoff_group_count] ||
      run_end - run_begin != 1u) {
    return 0;
  }
  const UF_long run =
    solver->refactor_supernode_algorithm5_payoff_group_current_runs[run_begin];
  if (run >= solver->refactor_supernode_consumer_plan_run_count ||
      !solver->refactor_supernode_algorithm5_payoff_run_selected[run]) {
    return 0;
  }
  *current_out = current;
  *run_out = run;
  return 1;
}

static int build_egraph_algorithm5_payoff_final_triggers(
  kls_solver *solver,
  UF_long **trigger_ptr_out,
  UF_long **trigger_slots_out) {
  if (trigger_ptr_out != NULL) {
    *trigger_ptr_out = NULL;
  }
  if (trigger_slots_out != NULL) {
    *trigger_slots_out = NULL;
  }
  if (solver == NULL || trigger_ptr_out == NULL ||
      trigger_slots_out == NULL || solver->n == 0u ||
      solver->refactor_supernode_algorithm5_payoff_group_current_total == 0u ||
      solver->refactor_supernode_algorithm5_payoff_group_currents == NULL ||
      solver->refactor_supernode_algorithm5_payoff_group_current_run_ptr ==
        NULL ||
      solver->refactor_supernode_algorithm5_payoff_group_current_runs ==
        NULL ||
      solver->refactor_supernode_algorithm5_payoff_group_ptr == NULL ||
      solver->refactor_supernode_algorithm5_payoff_run_selected == NULL) {
    return 0;
  }
  const UF_long current_total =
    solver->refactor_supernode_algorithm5_payoff_group_current_total;
  if (solver->n > (UF_long)(SIZE_MAX / sizeof(UF_long)) - 1u ||
      current_total > (UF_long)(SIZE_MAX / sizeof(UF_long))) {
    return 0;
  }

  UF_long *trigger_ptr =
    (UF_long *)calloc((size_t)(solver->n + 1u), sizeof(*trigger_ptr));
  if (trigger_ptr == NULL) {
    return 0;
  }

  UF_long trigger_count = 0u;
  for (UF_long slot = 0u; slot < current_total; ++slot) {
    const UF_long current =
      solver->refactor_supernode_algorithm5_payoff_group_currents[slot];
    const UF_long run_begin =
      solver->refactor_supernode_algorithm5_payoff_group_current_run_ptr[slot];
    const UF_long run_end =
      solver->refactor_supernode_algorithm5_payoff_group_current_run_ptr[
        slot + 1u];
    if (current >= solver->n || run_begin > run_end ||
        run_end >
          solver->refactor_supernode_algorithm5_payoff_group_ptr[
            solver->refactor_supernode_algorithm5_payoff_group_count] ||
        run_end - run_begin != 1u) {
      continue;
    }
    const UF_long run =
      solver->refactor_supernode_algorithm5_payoff_group_current_runs[
        run_begin];
    if (run >= solver->refactor_supernode_consumer_plan_run_count ||
        !solver->refactor_supernode_algorithm5_payoff_run_selected[run]) {
      continue;
    }
    UF_long final_dep = KLS_KLU_EMPTY;
    if (!kls_algorithm5_payoff_current_final_dep(
          solver, current, &final_dep) ||
        final_dep >= solver->n) {
      continue;
    }
    if (trigger_ptr[final_dep + 1u] == UF_long_max) {
      free(trigger_ptr);
      return 0;
    }
    trigger_ptr[final_dep + 1u]++;
    trigger_count++;
  }

  for (UF_long col = 0u; col < solver->n; ++col) {
    if (trigger_ptr[col] > UF_long_max - trigger_ptr[col + 1u]) {
      free(trigger_ptr);
      return 0;
    }
    trigger_ptr[col + 1u] += trigger_ptr[col];
  }
  if (trigger_ptr[solver->n] != trigger_count) {
    free(trigger_ptr);
    return 0;
  }

  UF_long *trigger_slots = NULL;
  UF_long *cursor = NULL;
  if (trigger_count > 0u) {
    trigger_slots =
      (UF_long *)malloc((size_t)trigger_count * sizeof(*trigger_slots));
    cursor = (UF_long *)malloc((size_t)solver->n * sizeof(*cursor));
    if (trigger_slots == NULL || cursor == NULL) {
      free(trigger_ptr);
      free(trigger_slots);
      free(cursor);
      return 0;
    }
    memcpy(cursor, trigger_ptr, (size_t)solver->n * sizeof(*cursor));
    for (UF_long slot = 0u; slot < current_total; ++slot) {
      const UF_long current =
        solver->refactor_supernode_algorithm5_payoff_group_currents[slot];
      const UF_long run_begin =
        solver->refactor_supernode_algorithm5_payoff_group_current_run_ptr[
          slot];
      const UF_long run_end =
        solver->refactor_supernode_algorithm5_payoff_group_current_run_ptr[
          slot + 1u];
      if (current >= solver->n || run_begin > run_end ||
          run_end >
            solver->refactor_supernode_algorithm5_payoff_group_ptr[
              solver->refactor_supernode_algorithm5_payoff_group_count] ||
          run_end - run_begin != 1u) {
        continue;
      }
      const UF_long run =
        solver->refactor_supernode_algorithm5_payoff_group_current_runs[
          run_begin];
      if (run >= solver->refactor_supernode_consumer_plan_run_count ||
          !solver->refactor_supernode_algorithm5_payoff_run_selected[run]) {
        continue;
      }
      UF_long final_dep = KLS_KLU_EMPTY;
      if (!kls_algorithm5_payoff_current_final_dep(
            solver, current, &final_dep) ||
          final_dep >= solver->n) {
        continue;
      }
      const UF_long dst = cursor[final_dep]++;
      if (dst >= trigger_ptr[final_dep + 1u]) {
        free(trigger_ptr);
        free(trigger_slots);
        free(cursor);
        return 0;
      }
      trigger_slots[dst] = slot;
    }
    free(cursor);
  }

  free(solver->egraph_algorithm5_payoff_final_trigger_ptr);
  free(solver->egraph_algorithm5_payoff_final_trigger_slots);
  solver->egraph_algorithm5_payoff_final_trigger_ptr = trigger_ptr;
  solver->egraph_algorithm5_payoff_final_trigger_slots = trigger_slots;
  solver->egraph_algorithm5_payoff_final_trigger_count = trigger_count;
  *trigger_ptr_out = trigger_ptr;
  *trigger_slots_out = trigger_slots;
  return 1;
}

static int build_egraph_algorithm5_payoff_suffix_triggers(
  kls_solver *solver,
  UF_long **trigger_ptr_out,
  UF_long **trigger_slots_out) {
  if (trigger_ptr_out != NULL) {
    *trigger_ptr_out = NULL;
  }
  if (trigger_slots_out != NULL) {
    *trigger_slots_out = NULL;
  }
  if (solver == NULL || trigger_ptr_out == NULL ||
      trigger_slots_out == NULL || solver->n == 0u ||
      solver->symbolic == NULL || solver->symbolic->R == NULL ||
      solver->numeric == NULL || solver->numeric->Ulen == NULL ||
      (solver->refactor_u_indices == NULL &&
       solver->refactor_u_indices32 == NULL) ||
      solver->refactor_supernode_algorithm5_payoff_group_current_total == 0u ||
      solver->refactor_supernode_algorithm5_payoff_run_advance_deps == NULL ||
      solver->refactor_supernode_algorithm5_payoff_run_prefix_rows == NULL) {
    return 0;
  }
  const UF_long current_total =
    solver->refactor_supernode_algorithm5_payoff_group_current_total;
  if (solver->n > (UF_long)(SIZE_MAX / sizeof(UF_long)) - 1u ||
      current_total > (UF_long)(SIZE_MAX / sizeof(UF_long))) {
    return 0;
  }

  UF_long *trigger_ptr =
    (UF_long *)calloc((size_t)(solver->n + 1u), sizeof(*trigger_ptr));
  if (trigger_ptr == NULL) {
    return 0;
  }

  UF_long trigger_count = 0u;
  for (UF_long slot = 0u; slot < current_total; ++slot) {
    UF_long current = KLS_KLU_EMPTY;
    UF_long run = KLS_KLU_EMPTY;
    if (!kls_algorithm5_payoff_current_slot_single_run(
          solver, slot, &current, &run)) {
      continue;
    }
    UF_long block = KLS_KLU_EMPTY;
    if (solver->symbolic->nblocks == 1u) {
      block = 0u;
    } else if (solver->refactor_col_block != NULL) {
      block = solver->refactor_col_block[current];
    } else {
      block = kls_block_for_pivot(solver, current);
    }
    if (block == KLS_KLU_EMPTY || block >= solver->symbolic->nblocks) {
      continue;
    }
    const UF_long k1 = solver->symbolic->R[block];
    const UF_long k2 = solver->symbolic->R[block + 1u];
    if (current < k1 || current >= k2) {
      continue;
    }
    const UF_long current_local = current - k1;
    const UF_long ulen = solver->numeric->Ulen[current];
    const UF_long advance_deps =
      solver->refactor_supernode_algorithm5_payoff_run_advance_deps[run];
    const UF_long prefix_rows =
      solver->refactor_supernode_algorithm5_payoff_run_prefix_rows[run];
    if (advance_deps > ulen || prefix_rows > ulen - advance_deps) {
      continue;
    }
    const UF_long prefix_end = advance_deps + prefix_rows;
    const int32_t *ui32 =
      solver->refactor_u_indices32 != NULL
        ? solver->refactor_u_indices32[current] : NULL;
    const UF_long *ui =
      ui32 == NULL && solver->refactor_u_indices != NULL
        ? solver->refactor_u_indices[current] : NULL;
    if (ulen > 0u && ui32 == NULL && ui == NULL) {
      continue;
    }
    for (UF_long p = prefix_end; p < ulen; ++p) {
      const UF_long dep_local = ui32 != NULL ? (UF_long)ui32[p] : ui[p];
      if (dep_local >= current_local || dep_local > UF_long_max - k1) {
        trigger_count = UF_long_max;
        break;
      }
      const UF_long dep = k1 + dep_local;
      if (dep >= current || dep >= solver->n ||
          trigger_ptr[dep + 1u] == UF_long_max ||
          trigger_count == UF_long_max) {
        trigger_count = UF_long_max;
        break;
      }
      trigger_ptr[dep + 1u]++;
      trigger_count++;
    }
    if (trigger_count == UF_long_max) {
      break;
    }
  }
  if (trigger_count == UF_long_max) {
    free(trigger_ptr);
    return 0;
  }

  for (UF_long col = 0u; col < solver->n; ++col) {
    if (trigger_ptr[col] > UF_long_max - trigger_ptr[col + 1u]) {
      free(trigger_ptr);
      return 0;
    }
    trigger_ptr[col + 1u] += trigger_ptr[col];
  }
  if (trigger_ptr[solver->n] != trigger_count) {
    free(trigger_ptr);
    return 0;
  }

  UF_long *trigger_slots = NULL;
  UF_long *cursor = NULL;
  if (trigger_count > 0u) {
    trigger_slots =
      (UF_long *)malloc((size_t)trigger_count * sizeof(*trigger_slots));
    cursor = (UF_long *)malloc((size_t)solver->n * sizeof(*cursor));
    if (trigger_slots == NULL || cursor == NULL) {
      free(trigger_ptr);
      free(trigger_slots);
      free(cursor);
      return 0;
    }
    memcpy(cursor, trigger_ptr, (size_t)solver->n * sizeof(*cursor));
    for (UF_long slot = 0u; slot < current_total; ++slot) {
      UF_long current = KLS_KLU_EMPTY;
      UF_long run = KLS_KLU_EMPTY;
      if (!kls_algorithm5_payoff_current_slot_single_run(
            solver, slot, &current, &run)) {
        continue;
      }
      UF_long block = KLS_KLU_EMPTY;
      if (solver->symbolic->nblocks == 1u) {
        block = 0u;
      } else if (solver->refactor_col_block != NULL) {
        block = solver->refactor_col_block[current];
      } else {
        block = kls_block_for_pivot(solver, current);
      }
      if (block == KLS_KLU_EMPTY || block >= solver->symbolic->nblocks) {
        continue;
      }
      const UF_long k1 = solver->symbolic->R[block];
      const UF_long k2 = solver->symbolic->R[block + 1u];
      if (current < k1 || current >= k2) {
        continue;
      }
      const UF_long current_local = current - k1;
      const UF_long ulen = solver->numeric->Ulen[current];
      const UF_long advance_deps =
        solver->refactor_supernode_algorithm5_payoff_run_advance_deps[run];
      const UF_long prefix_rows =
        solver->refactor_supernode_algorithm5_payoff_run_prefix_rows[run];
      if (advance_deps > ulen || prefix_rows > ulen - advance_deps) {
        continue;
      }
      const UF_long prefix_end = advance_deps + prefix_rows;
      const int32_t *ui32 =
        solver->refactor_u_indices32 != NULL
          ? solver->refactor_u_indices32[current] : NULL;
      const UF_long *ui =
        ui32 == NULL && solver->refactor_u_indices != NULL
          ? solver->refactor_u_indices[current] : NULL;
      if (ulen > 0u && ui32 == NULL && ui == NULL) {
        continue;
      }
      for (UF_long p = prefix_end; p < ulen; ++p) {
        const UF_long dep_local = ui32 != NULL ? (UF_long)ui32[p] : ui[p];
        if (dep_local >= current_local || dep_local > UF_long_max - k1) {
          free(trigger_ptr);
          free(trigger_slots);
          free(cursor);
          return 0;
        }
        const UF_long dep = k1 + dep_local;
        if (dep >= solver->n) {
          free(trigger_ptr);
          free(trigger_slots);
          free(cursor);
          return 0;
        }
        const UF_long dst = cursor[dep]++;
        if (dst >= trigger_ptr[dep + 1u]) {
          free(trigger_ptr);
          free(trigger_slots);
          free(cursor);
          return 0;
        }
        trigger_slots[dst] = slot;
      }
    }
    free(cursor);
  }

  free(solver->egraph_algorithm5_payoff_suffix_trigger_ptr);
  free(solver->egraph_algorithm5_payoff_suffix_trigger_slots);
  solver->egraph_algorithm5_payoff_suffix_trigger_ptr = trigger_ptr;
  solver->egraph_algorithm5_payoff_suffix_trigger_slots = trigger_slots;
  solver->egraph_algorithm5_payoff_suffix_trigger_count = trigger_count;
  *trigger_ptr_out = trigger_ptr;
  *trigger_slots_out = trigger_slots;
  return 1;
}

static int build_egraph_algorithm5_payoff_suffix_entry_triggers(
  kls_solver *solver,
  UF_long **solver_trigger_ptr,
  UF_long **solver_trigger_entries,
  UF_long *solver_trigger_count,
  UF_long **trigger_ptr_out,
  UF_long **trigger_entries_out) {
  if (trigger_ptr_out != NULL) {
    *trigger_ptr_out = NULL;
  }
  if (trigger_entries_out != NULL) {
    *trigger_entries_out = NULL;
  }
  if (solver == NULL || solver_trigger_ptr == NULL ||
      solver_trigger_entries == NULL || solver_trigger_count == NULL ||
      trigger_ptr_out == NULL ||
      trigger_entries_out == NULL || solver->n == 0u ||
      solver->refactor_supernode_algorithm5_payoff_group_count == 0u ||
      solver->refactor_supernode_algorithm5_payoff_group_suffix_ptr == NULL ||
      solver->refactor_supernode_algorithm5_payoff_group_suffix_run_ptr ==
        NULL) {
    return 0;
  }
  const UF_long group_count =
    solver->refactor_supernode_algorithm5_payoff_group_count;
  const UF_long entry_count =
    solver->refactor_supernode_algorithm5_payoff_group_suffix_ptr[
      group_count];
  if (solver->n > (UF_long)(SIZE_MAX / sizeof(UF_long)) - 1u ||
      entry_count > (UF_long)(SIZE_MAX / sizeof(UF_long))) {
    return 0;
  }
  if (entry_count > 0u &&
      solver->refactor_supernode_algorithm5_payoff_group_suffix_cols == NULL) {
    return 0;
  }
  if (solver->refactor_supernode_algorithm5_payoff_group_suffix_deps_total >
        0u &&
      (solver->refactor_supernode_algorithm5_payoff_group_suffix_runs == NULL ||
       solver->refactor_supernode_algorithm5_payoff_group_suffix_up == NULL)) {
    return 0;
  }

  UF_long *trigger_ptr =
    (UF_long *)calloc((size_t)(solver->n + 1u), sizeof(*trigger_ptr));
  if (trigger_ptr == NULL) {
    return 0;
  }

  for (UF_long entry = 0u; entry < entry_count; ++entry) {
    const UF_long dep =
      solver->refactor_supernode_algorithm5_payoff_group_suffix_cols[entry];
    const UF_long begin =
      solver->refactor_supernode_algorithm5_payoff_group_suffix_run_ptr[
        entry];
    const UF_long end =
      solver->refactor_supernode_algorithm5_payoff_group_suffix_run_ptr[
        entry + 1u];
    if (dep >= solver->n || begin > end ||
        end >
          solver->refactor_supernode_algorithm5_payoff_group_suffix_deps_total ||
        trigger_ptr[dep + 1u] == UF_long_max) {
      free(trigger_ptr);
      return 0;
    }
    trigger_ptr[dep + 1u]++;
  }

  for (UF_long col = 0u; col < solver->n; ++col) {
    if (trigger_ptr[col] > UF_long_max - trigger_ptr[col + 1u]) {
      free(trigger_ptr);
      return 0;
    }
    trigger_ptr[col + 1u] += trigger_ptr[col];
  }
  if (trigger_ptr[solver->n] != entry_count) {
    free(trigger_ptr);
    return 0;
  }

  UF_long *trigger_entries = NULL;
  UF_long *cursor = NULL;
  if (entry_count > 0u) {
    trigger_entries =
      (UF_long *)malloc((size_t)entry_count * sizeof(*trigger_entries));
    cursor = (UF_long *)malloc((size_t)solver->n * sizeof(*cursor));
    if (trigger_entries == NULL || cursor == NULL) {
      free(trigger_ptr);
      free(trigger_entries);
      free(cursor);
      return 0;
    }
    memcpy(cursor, trigger_ptr, (size_t)solver->n * sizeof(*cursor));
    for (UF_long entry = 0u; entry < entry_count; ++entry) {
      const UF_long dep =
        solver->refactor_supernode_algorithm5_payoff_group_suffix_cols[entry];
      if (dep >= solver->n) {
        free(trigger_ptr);
        free(trigger_entries);
        free(cursor);
        return 0;
      }
      const UF_long dst = cursor[dep]++;
      if (dst >= trigger_ptr[dep + 1u]) {
        free(trigger_ptr);
        free(trigger_entries);
        free(cursor);
        return 0;
      }
      trigger_entries[dst] = entry;
    }
    free(cursor);
  }

  free(*solver_trigger_ptr);
  free(*solver_trigger_entries);
  *solver_trigger_ptr = trigger_ptr;
  *solver_trigger_entries = trigger_entries;
  *solver_trigger_count = entry_count;
  *trigger_ptr_out = trigger_ptr;
  *trigger_entries_out = trigger_entries;
  return 1;
}

static int build_egraph_algorithm5_payoff_suffix_group_triggers(
  kls_solver *solver,
  UF_long **trigger_ptr_out,
  UF_long **trigger_entries_out) {
  return build_egraph_algorithm5_payoff_suffix_entry_triggers(
    solver, &solver->egraph_algorithm5_payoff_suffix_group_trigger_ptr,
    &solver->egraph_algorithm5_payoff_suffix_group_trigger_entries,
    &solver->egraph_algorithm5_payoff_suffix_group_trigger_count,
    trigger_ptr_out, trigger_entries_out);
}

static int build_egraph_algorithm5_payoff_suffix_producer_triggers(
  kls_solver *solver,
  UF_long **trigger_ptr_out,
  UF_long **trigger_entries_out) {
  return build_egraph_algorithm5_payoff_suffix_entry_triggers(
    solver, &solver->egraph_algorithm5_payoff_suffix_producer_trigger_ptr,
    &solver->egraph_algorithm5_payoff_suffix_producer_trigger_entries,
    &solver->egraph_algorithm5_payoff_suffix_producer_trigger_count,
    trigger_ptr_out, trigger_entries_out);
}

static int ensure_egraph_algorithm5_payoff_queue(
  kls_solver *solver,
  UF_long capacity,
  UF_long **cols_out,
  atomic_uint **slots_out,
  unsigned char **flags_out) {
  if (cols_out != NULL) {
    *cols_out = NULL;
  }
  if (slots_out != NULL) {
    *slots_out = NULL;
  }
  if (flags_out != NULL) {
    *flags_out = NULL;
  }
  if (solver == NULL || capacity == 0u || cols_out == NULL ||
      slots_out == NULL || flags_out == NULL ||
      capacity > (UF_long)(SIZE_MAX / sizeof(UF_long)) ||
      capacity > (UF_long)(SIZE_MAX / sizeof(atomic_uint)) ||
      capacity > (UF_long)PTRDIFF_MAX) {
    return 0;
  }
  if (solver->egraph_algorithm5_payoff_queue_cols == NULL ||
      solver->egraph_algorithm5_payoff_queue_slots == NULL ||
      solver->egraph_algorithm5_payoff_queue_flags == NULL ||
      solver->egraph_algorithm5_payoff_queue_size < capacity) {
    free_egraph_algorithm5_payoff_queue(solver);
    solver->egraph_algorithm5_payoff_queue_cols =
      (UF_long *)malloc((size_t)capacity *
                        sizeof(*solver->egraph_algorithm5_payoff_queue_cols));
    solver->egraph_algorithm5_payoff_queue_slots =
      (atomic_uint *)malloc(
        (size_t)capacity *
        sizeof(*solver->egraph_algorithm5_payoff_queue_slots));
    solver->egraph_algorithm5_payoff_queue_flags =
      (unsigned char *)malloc(
        (size_t)capacity *
        sizeof(*solver->egraph_algorithm5_payoff_queue_flags));
    if (solver->egraph_algorithm5_payoff_queue_cols == NULL ||
        solver->egraph_algorithm5_payoff_queue_slots == NULL ||
        solver->egraph_algorithm5_payoff_queue_flags == NULL) {
      free_egraph_algorithm5_payoff_queue(solver);
      return 0;
    }
    solver->egraph_algorithm5_payoff_queue_size = capacity;
    for (UF_long k = 0u; k < capacity; ++k) {
      solver->egraph_algorithm5_payoff_queue_cols[k] = 0u;
      solver->egraph_algorithm5_payoff_queue_flags[k] = 0u;
      atomic_init(&solver->egraph_algorithm5_payoff_queue_slots[k], 0u);
    }
  } else {
    for (UF_long k = 0u; k < capacity; ++k) {
      solver->egraph_algorithm5_payoff_queue_cols[k] = 0u;
      solver->egraph_algorithm5_payoff_queue_flags[k] = 0u;
      atomic_store_explicit(&solver->egraph_algorithm5_payoff_queue_slots[k],
                            0u, memory_order_relaxed);
    }
  }
  *cols_out = solver->egraph_algorithm5_payoff_queue_cols;
  *slots_out = solver->egraph_algorithm5_payoff_queue_slots;
  *flags_out = solver->egraph_algorithm5_payoff_queue_flags;
  return 1;
}

static int ensure_egraph_algorithm5_payoff_runtime_state(
  kls_solver *solver,
  UF_long workspace_rows,
  UF_long target_slots,
  UF_long advance_slots,
  UF_long advance_deps,
  UF_long current_state_rows,
  UF_long current_count,
  double **workspace_values_out,
  double **target_values_out,
  double **advance_values_out,
  double **advance_u_values_out,
  double **current_state_values_out,
  atomic_uchar **current_flags_out,
  atomic_ulong **current_up_out) {
  if (workspace_values_out != NULL) {
    *workspace_values_out = NULL;
  }
  if (target_values_out != NULL) {
    *target_values_out = NULL;
  }
  if (advance_values_out != NULL) {
    *advance_values_out = NULL;
  }
  if (advance_u_values_out != NULL) {
    *advance_u_values_out = NULL;
  }
  if (current_state_values_out != NULL) {
    *current_state_values_out = NULL;
  }
  if (current_flags_out != NULL) {
    *current_flags_out = NULL;
  }
  if (current_up_out != NULL) {
    *current_up_out = NULL;
  }
  const size_t workspace_row_count = (size_t)workspace_rows;
  const size_t target_slot_count = (size_t)target_slots;
  const size_t advance_slot_count = (size_t)advance_slots;
  const size_t advance_dep_count = (size_t)advance_deps;
  const size_t current_state_row_count = (size_t)current_state_rows;
  const size_t current_slot_count = (size_t)current_count;
  if (solver == NULL || workspace_values_out == NULL ||
      target_values_out == NULL || advance_values_out == NULL ||
      advance_u_values_out == NULL || current_state_values_out == NULL ||
      current_flags_out == NULL || current_up_out == NULL ||
      (UF_long)workspace_row_count != workspace_rows ||
      (UF_long)target_slot_count != target_slots ||
      (UF_long)advance_slot_count != advance_slots ||
      (UF_long)advance_dep_count != advance_deps ||
      (UF_long)current_state_row_count != current_state_rows ||
      (UF_long)current_slot_count != current_count ||
      workspace_row_count > SIZE_MAX / sizeof(double) ||
      target_slot_count > SIZE_MAX / sizeof(double) ||
      advance_slot_count > SIZE_MAX / sizeof(double) ||
      advance_dep_count > SIZE_MAX / sizeof(double) ||
      current_state_row_count > SIZE_MAX / sizeof(double) ||
      current_slot_count > SIZE_MAX / sizeof(atomic_uchar) ||
      current_slot_count > SIZE_MAX / sizeof(atomic_ulong) ||
      workspace_row_count > (size_t)PTRDIFF_MAX ||
      target_slot_count > (size_t)PTRDIFF_MAX ||
      advance_slot_count > (size_t)PTRDIFF_MAX ||
      advance_dep_count > (size_t)PTRDIFF_MAX ||
      current_state_row_count > (size_t)PTRDIFF_MAX ||
      current_slot_count > (size_t)PTRDIFF_MAX) {
    return 0;
  }
  if (workspace_rows > 0u &&
      (solver->egraph_algorithm5_payoff_workspace_values == NULL ||
       solver->egraph_algorithm5_payoff_workspace_size < workspace_rows)) {
    double *values =
      (double *)realloc(solver->egraph_algorithm5_payoff_workspace_values,
                        workspace_row_count *
                          sizeof(*solver
                                     ->egraph_algorithm5_payoff_workspace_values));
    if (values == NULL) {
      return 0;
    }
    solver->egraph_algorithm5_payoff_workspace_values = values;
    solver->egraph_algorithm5_payoff_workspace_size = workspace_rows;
  }
  if (target_slots > 0u &&
      (solver->egraph_algorithm5_payoff_target_values == NULL ||
       solver->egraph_algorithm5_payoff_target_size < target_slots)) {
    double *values =
      (double *)realloc(solver->egraph_algorithm5_payoff_target_values,
                        target_slot_count *
                          sizeof(*solver
                                     ->egraph_algorithm5_payoff_target_values));
    if (values == NULL) {
      return 0;
    }
    solver->egraph_algorithm5_payoff_target_values = values;
    solver->egraph_algorithm5_payoff_target_size = target_slots;
  }
  if (advance_slots > 0u &&
      (solver->egraph_algorithm5_payoff_advance_values == NULL ||
       solver->egraph_algorithm5_payoff_advance_size < advance_slots)) {
    double *values =
      (double *)realloc(solver->egraph_algorithm5_payoff_advance_values,
                        advance_slot_count *
                          sizeof(*solver
                                     ->egraph_algorithm5_payoff_advance_values));
    if (values == NULL) {
      return 0;
    }
    solver->egraph_algorithm5_payoff_advance_values = values;
    solver->egraph_algorithm5_payoff_advance_size = advance_slots;
  }
  if (advance_deps > 0u &&
      (solver->egraph_algorithm5_payoff_advance_u_values == NULL ||
       solver->egraph_algorithm5_payoff_advance_u_size < advance_deps)) {
    double *values =
      (double *)realloc(
        solver->egraph_algorithm5_payoff_advance_u_values,
        advance_dep_count *
          sizeof(*solver->egraph_algorithm5_payoff_advance_u_values));
    if (values == NULL) {
      return 0;
    }
    solver->egraph_algorithm5_payoff_advance_u_values = values;
    solver->egraph_algorithm5_payoff_advance_u_size = advance_deps;
  }
  if (current_state_rows > 0u &&
      (solver->egraph_algorithm5_payoff_current_state_values == NULL ||
       solver->egraph_algorithm5_payoff_current_state_size <
         current_state_rows)) {
    double *values =
      (double *)realloc(
        solver->egraph_algorithm5_payoff_current_state_values,
        current_state_row_count *
          sizeof(*solver->egraph_algorithm5_payoff_current_state_values));
    if (values == NULL) {
      return 0;
    }
    solver->egraph_algorithm5_payoff_current_state_values = values;
    solver->egraph_algorithm5_payoff_current_state_size = current_state_rows;
  }
  if (current_count > 0u &&
      (solver->egraph_algorithm5_payoff_current_flags == NULL ||
       solver->egraph_algorithm5_payoff_current_flags_size < current_count)) {
    atomic_uchar *flags =
      (atomic_uchar *)realloc(
        solver->egraph_algorithm5_payoff_current_flags,
        current_slot_count *
          sizeof(*solver->egraph_algorithm5_payoff_current_flags));
    if (flags == NULL) {
      return 0;
    }
    solver->egraph_algorithm5_payoff_current_flags = flags;
    solver->egraph_algorithm5_payoff_current_flags_size = current_count;
  }
  if (current_count > 0u &&
      (solver->egraph_algorithm5_payoff_current_up == NULL ||
       solver->egraph_algorithm5_payoff_current_up_size < current_count)) {
    atomic_ulong *current_up =
      (atomic_ulong *)realloc(
        solver->egraph_algorithm5_payoff_current_up,
        current_slot_count *
          sizeof(*solver->egraph_algorithm5_payoff_current_up));
    if (current_up == NULL) {
      return 0;
    }
    solver->egraph_algorithm5_payoff_current_up = current_up;
    solver->egraph_algorithm5_payoff_current_up_size = current_count;
  }
  if (workspace_rows > 0u) {
    memset(solver->egraph_algorithm5_payoff_workspace_values, 0,
           workspace_row_count *
             sizeof(*solver->egraph_algorithm5_payoff_workspace_values));
  }
  if (target_slots > 0u) {
    memset(solver->egraph_algorithm5_payoff_target_values, 0,
           target_slot_count *
             sizeof(*solver->egraph_algorithm5_payoff_target_values));
  }
  if (advance_slots > 0u) {
    memset(solver->egraph_algorithm5_payoff_advance_values, 0,
           advance_slot_count *
             sizeof(*solver->egraph_algorithm5_payoff_advance_values));
  }
  if (advance_deps > 0u) {
    memset(solver->egraph_algorithm5_payoff_advance_u_values, 0,
           advance_dep_count *
             sizeof(*solver->egraph_algorithm5_payoff_advance_u_values));
  }
  if (current_state_rows > 0u) {
    memset(
      solver->egraph_algorithm5_payoff_current_state_values, 0,
      current_state_row_count *
        sizeof(*solver->egraph_algorithm5_payoff_current_state_values));
  }
  if (current_count > 0u) {
    for (UF_long slot = 0u; slot < current_count; ++slot) {
      atomic_store_explicit(
        &solver->egraph_algorithm5_payoff_current_flags[slot], 0u,
        memory_order_relaxed);
      atomic_store_explicit(
        &solver->egraph_algorithm5_payoff_current_up[slot], 0ul,
        memory_order_relaxed);
    }
  }
  *workspace_values_out =
    workspace_rows > 0u ? solver->egraph_algorithm5_payoff_workspace_values
                        : NULL;
  *target_values_out =
    target_slots > 0u ? solver->egraph_algorithm5_payoff_target_values : NULL;
  *advance_values_out =
    advance_slots > 0u ? solver->egraph_algorithm5_payoff_advance_values
                       : NULL;
  *advance_u_values_out =
    advance_deps > 0u ? solver->egraph_algorithm5_payoff_advance_u_values
                      : NULL;
  *current_state_values_out =
    current_state_rows > 0u
      ? solver->egraph_algorithm5_payoff_current_state_values
      : NULL;
  *current_flags_out =
    current_count > 0u ? solver->egraph_algorithm5_payoff_current_flags : NULL;
  *current_up_out =
    current_count > 0u ? solver->egraph_algorithm5_payoff_current_up : NULL;
  return 1;
}

static int kls_prepare_refactor_algorithm5_payoff_runtime_state(
  kls_solver *solver,
  int *active_out,
  double **workspace_values_out,
  UF_long *workspace_size_out,
  double **target_values_out,
  UF_long *target_size_out,
  atomic_uchar **current_flags_out,
  UF_long *current_count_out) {
  if (active_out != NULL) {
    *active_out = 0;
  }
  if (workspace_values_out != NULL) {
    *workspace_values_out = NULL;
  }
  if (workspace_size_out != NULL) {
    *workspace_size_out = 0u;
  }
  if (target_values_out != NULL) {
    *target_values_out = NULL;
  }
  if (target_size_out != NULL) {
    *target_size_out = 0u;
  }
  if (current_flags_out != NULL) {
    *current_flags_out = NULL;
  }
  if (current_count_out != NULL) {
    *current_count_out = 0u;
  }
  if (solver == NULL || active_out == NULL ||
      workspace_values_out == NULL || workspace_size_out == NULL ||
      target_values_out == NULL || target_size_out == NULL ||
      current_flags_out == NULL || current_count_out == NULL) {
    return 0;
  }
  solver->refactor_supernode_algorithm5_payoff_runtime_workspace_rows = 0u;
  solver->refactor_supernode_algorithm5_payoff_runtime_target_slots = 0u;
  solver->refactor_supernode_algorithm5_payoff_runtime_current_count = 0u;
  if (!kls_refactor_supernode_algorithm5_payoff_runtime_env_enabled() ||
      solver->refactor_supernode_algorithm5_payoff_group_count == 0u ||
      solver->refactor_supernode_algorithm5_payoff_group_current_total == 0u) {
    return 1;
  }
  const UF_long workspace_size =
    solver->refactor_supernode_algorithm5_payoff_group_workspace_rows_total;
  const UF_long target_size =
    kls_refactor_supernode_algorithm5_payoff_runtime_target_size(solver);
  const int suffix_advance =
    kls_refactor_supernode_algorithm5_payoff_suffix_advance_env_enabled();
  const int suffix_group_advance =
    kls_refactor_supernode_algorithm5_payoff_suffix_group_advance_env_enabled() ||
    kls_refactor_supernode_algorithm5_payoff_suffix_group_window_env_enabled();
  const int suffix_producer_advance =
    kls_refactor_supernode_algorithm5_payoff_suffix_producer_advance_env_enabled();
  const int advance_seed =
    kls_refactor_supernode_algorithm5_payoff_direct_prefix_advance_seed_env_enabled();
  const int current_state_seed =
    kls_refactor_supernode_algorithm5_payoff_direct_prefix_current_state_env_enabled() ||
    suffix_advance || suffix_group_advance || suffix_producer_advance;
  const UF_long advance_size =
    advance_seed
      ? solver->refactor_supernode_algorithm5_payoff_group_advance_slots_total
      : 0u;
  const UF_long advance_u_size =
    (advance_seed || current_state_seed)
      ? solver->refactor_supernode_algorithm5_payoff_group_advance_deps_total
      : 0u;
  const UF_long current_state_size =
    current_state_seed
      ? solver->refactor_supernode_algorithm5_payoff_current_state_rows_total
      : 0u;
  const UF_long current_count =
    solver->refactor_supernode_algorithm5_payoff_group_current_total;
  double *workspace_values = NULL;
  double *target_values = NULL;
  double *advance_values = NULL;
  double *advance_u_values = NULL;
  double *current_state_values = NULL;
  atomic_uchar *current_flags = NULL;
  atomic_ulong *current_up = NULL;
  if (!ensure_egraph_algorithm5_payoff_runtime_state(
        solver, workspace_size, target_size, advance_size, advance_u_size,
        current_state_size, current_count, &workspace_values, &target_values,
        &advance_values, &advance_u_values, &current_state_values,
        &current_flags, &current_up)) {
    return 0;
  }
  (void)current_up;
  *active_out = 1;
  *workspace_values_out = workspace_values;
  *workspace_size_out = workspace_size;
  *target_values_out = target_values;
  *target_size_out = target_size;
  *current_flags_out = current_flags;
  *current_count_out = current_count;
  solver->refactor_supernode_algorithm5_payoff_runtime_workspace_rows =
    workspace_size;
  solver->refactor_supernode_algorithm5_payoff_runtime_target_slots =
    target_size;
  solver->refactor_supernode_algorithm5_payoff_runtime_current_count =
    current_count;
  return 1;
}

static void kls_worker_record_singular(kls_parallel_refactor_worker *worker,
                                       UF_long numerical_rank,
                                       UF_long singular_col) {
  if (!worker->singular || numerical_rank < worker->numerical_rank) {
    worker->singular = 1;
    worker->numerical_rank = numerical_rank;
    worker->singular_col = singular_col;
  }
  {
    kls_solver *solver = worker->shared->solver;
    if (solver->zero_pivot_collect != NULL) {
      const long slot = atomic_fetch_add_explicit(
        &solver->zero_pivot_collect_count, 1, memory_order_relaxed);
      if (slot < solver->zero_pivot_collect_cap) {
        solver->zero_pivot_collect[slot] = numerical_rank;
      }
    }
  }
}

static void kls_record_fast_factor_failure(kls_solver *solver,
                                           int reason,
                                           int status) {
  if (solver == NULL || reason == KLS_FAST_FACTOR_FAIL_NONE) {
    return;
  }
  if (solver->stats.fast_factor_fail_reason == KLS_FAST_FACTOR_FAIL_NONE) {
    solver->stats.fast_factor_fail_reason = reason;
    solver->stats.fast_factor_fail_status = status;
  }
}

